led\" @click=\"handleSave\">\n        <i class=\"pi pi-check\" />\n        {{ saveButtonText }}\n      </Button>\n      <Button variant=\"secondary\" @click=\"handleCancel\">\n        <i class=\"pi pi-times\" />\n        {{ t('g.cancel') }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCanvasTools } from '@/composables/maskeditor/useCanvasTools'\nimport { useCanvasTransform } from '@/composables/maskeditor/useCanvasTransform'\nimport { useMaskEditorSaver } from '@/composables/maskeditor/useMaskEditorSaver'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\n\nconst { t } = useI18n()\nconst store = useMaskEditorStore()\nconst dialogStore = useDialogStore()\nconst canvasTools = useCanvasTools()\nconst canvasTransform = useCanvasTransform()\nconst saver = useMaskEditorSaver()\n\nconst saveButtonText = ref(t('g.save'))\nconst saveEnabled = ref(true)\n\nconst iconButtonClass =\n  'flex h-7.5 w-12.5 items-center justify-center rounded-[10px] border border-border-default pointer-events-auto transition-colors duration-100 bg-comfy-menu-bg hover:bg-secondary-background-hover'\n\nconst textButtonClass =\n  'h-7.5 w-15 rounded-[10px] border border-border-default text-current font-sans pointer-events-auto transition-colors duration-100 bg-comfy-menu-bg hover:bg-secondary-background-hover'\n\nconst onUndo = () => {\n  store.canvasHistory.undo()\n}\n\nconst onRedo = () => {\n  store.canvasHistory.redo()\n}\n\nconst onRotateLeft = async () => {\n  try {\n    await canvasTransform.rotateCounterclockwise()\n  } catch (error) {\n    console.error('[TopBarHeader] Rotate left failed:', error)\n  }\n}\n\nconst onRotateRight = async () => {\n  try {\n    await canvasTransform.rotateClockwise()\n  } catch (error) {\n    console.error('[TopBarHeader] Rotate right failed:', error)\n  }\n}\n\nconst onMirrorHorizontal = async () => {\n  try {\n    await canvasTransform.mirrorHorizontal()\n  } catch (error) {\n    console.error('[TopBarHeader] Mirror horizontal failed:', error)\n  }\n}\n\nconst onMirrorVertical = async () => {\n  try {\n    await canvasTransform.mirrorVertical()\n  } catch (error) {\n    console.error('[TopBarHeader] Mirror vertical failed:', error)\n  }\n}\n\nconst onInvert = () => {\n  canvasTools.invertMask()\n}\n\nconst onClear = () => {\n  canvasTools.clearMask()\n  store.triggerClear()\n}\n\nconst handleSave = async () => {\n  saveButtonText.value = t('g.saving')\n  saveEnabled.value = false\n\n  try {\n    store.brushVisible = false\n    await saver.save()\n    dialogStore.closeDialog()\n  } catch (error) {\n    console.error('[TopBarHeader] Save failed:', error)\n    store.brushVisible = true\n    saveButtonText.value = t('g.save')\n    saveEnabled.value = true\n  }\n}\n\nconst handleCancel = () => {\n  dialogStore.closeDialog({ key: 'global-mask-editor' })\n}\n</script>\n","import { useMaskEditorStore } from '@/stores/maskEditorStore'\n\nimport { MaskBlendMode } from '@/extensions/core/maskeditor/types'\n\nexport function useCanvasManager() {\n  const store = useMaskEditorStore()\n\n  const prepareMask = async (\n    image: HTMLImageElement,\n    maskCanvasEl: HTMLCanvasElement,\n    maskContext: CanvasRenderingContext2D\n  ): Promise<void> => {\n    const maskColor = store.maskColor\n\n    maskContext.drawImage(image, 0, 0, maskCanvasEl.width, maskCanvasEl.height)\n\n    const maskData = maskContext.getImageData(\n      0,\n      0,\n      maskCanvasEl.width,\n      maskCanvasEl.height\n    )\n\n    for (let i = 0; i < maskData.data.length; i += 4) {\n      const alpha = maskData.data[i + 3]\n      maskData.data[i] = maskColor.r\n      maskData.data[i + 1] = maskColor.g\n      maskData.data[i + 2] = maskColor.b\n      maskData.data[i + 3] = 255 - alpha\n    }\n\n    maskContext.globalCompositeOperation = 'source-over'\n    maskContext.putImageData(maskData, 0, 0)\n  }\n\n  const invalidateCanvas = async (\n    origImage: HTMLImageElement,\n    maskImage: HTMLImageElement,\n    paintImage: HTMLImageElement | null\n  ): Promise<void> => {\n    const { imgCanvas, maskCanvas, rgbCanvas, imgCtx, maskCtx, rgbCtx } = store\n\n    if (\n      !imgCanvas ||\n      !maskCanvas ||\n      !rgbCanvas ||\n      !imgCtx ||\n      !maskCtx ||\n      !rgbCtx\n    ) {\n      throw new Error('Canvas elements or contexts not available')\n    }\n\n    imgCanvas.width = origImage.width\n    imgCanvas.height = origImage.height\n    maskCanvas.width = origImage.width\n    maskCanvas.height = origImage.height\n    rgbCanvas.width = origImage.width\n    rgbCanvas.height = origImage.height\n\n    imgCtx.drawImage(origImage, 0, 0, origImage.width, origImage.height)\n\n    if (paintImage) {\n      rgbCtx.drawImage(paintImage, 0, 0, paintImage.width, paintImage.height)\n    }\n\n    await prepareMask(maskImage, maskCanvas, maskCtx)\n  }\n\n  const setCanvasBackground = (): void => {\n    const canvasBackground = store.canvasBackground\n\n    if (!canvasBackground) return\n\n    if (store.maskBlendMode === MaskBlendMode.Black) {\n      canvasBackground.style.backgroundColor = 'rgba(0,0,0,1)'\n    } else if (store.maskBlendMode === MaskBlendMode.White) {\n      canvasBackground.style.backgroundColor = 'rgba(255,255,255,1)'\n    } else {\n      canvasBackground.style.backgroundColor = 'rgba(255,255,255,1)'\n    }\n  }\n\n  const updateMaskColor = async (): Promise<void> => {\n    const { maskCanvas, maskCtx, maskColor, maskBlendMode, maskOpacity } = store\n\n    if (!maskCanvas || !maskCtx) return\n\n    if (maskBlendMode === MaskBlendMode.Negative) {\n      maskCanvas.style.mixBlendMode = 'difference'\n      maskCanvas.style.opacity = '1'\n    } else {\n      maskCanvas.style.mixBlendMode = 'initial'\n      maskCanvas.style.opacity = String(maskOpacity)\n    }\n\n    maskCtx.fillStyle = `rgb(${maskColor.r}, ${maskColor.g}, ${maskColor.b})`\n\n    setCanvasBackground()\n\n    const maskData = maskCtx.getImageData(\n      0,\n      0,\n      maskCanvas.width,\n      maskCanvas.height\n    )\n\n    for (let i = 0; i < maskData.data.length; i += 4) {\n      maskData.data[i] = maskColor.r\n      maskData.data[i + 1] = maskColor.g\n      maskData.data[i + 2] = maskColor.b\n    }\n\n    maskCtx.putImageData(maskData, 0, 0)\n  }\n\n  return {\n    invalidateCanvas,\n    updateMaskColor\n  }\n}\n","import { useMaskEditorStore } from '@/stores/maskEditorStore'\nimport { useMaskEditorDataStore } from '@/stores/maskEditorDataStore'\nimport { createSharedComposable } from '@vueuse/core'\nimport { useCanvasManager } from '@/composables/maskeditor/useCanvasManager'\n\nfunction useImageLoaderInternal() {\n  const store = useMaskEditorStore()\n  const dataStore = useMaskEditorDataStore()\n  const canvasManager = useCanvasManager()\n\n  const loadImages = async (): Promise<HTMLImageElement> => {\n    const inputData = dataStore.inputData\n\n    if (!inputData) {\n      throw new Error('No input data available in dataStore')\n    }\n\n    const { imgCanvas, maskCanvas, rgbCanvas, imgCtx, maskCtx } = store\n\n    if (!imgCanvas || !maskCanvas || !rgbCanvas || !imgCtx || !maskCtx) {\n      throw new Error('Canvas elements or contexts not available')\n    }\n\n    imgCtx.clearRect(0, 0, imgCanvas.width, imgCanvas.height)\n    maskCtx.clearRect(0, 0, maskCanvas.width, maskCanvas.height)\n\n    const baseImage = inputData.baseLayer.image\n    const maskImage = inputData.maskLayer.image\n    const paintImage = inputData.paintLayer?.image\n\n    maskCanvas.width = baseImage.width\n    maskCanvas.height = baseImage.height\n    rgbCanvas.width = baseImage.width\n    rgbCanvas.height = baseImage.height\n\n    store.image = baseImage\n\n    await canvasManager.invalidateCanvas(\n      baseImage,\n      maskImage,\n      paintImage || null\n    )\n\n    await canvasManager.updateMaskColor()\n\n    return baseImage\n  }\n\n  return {\n    loadImages\n  }\n}\n\nexport const useImageLoader = createSharedComposable(useImageLoaderInternal)\n","import { ref } from 'vue'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\n\nexport function useKeyboard() {\n  const store = useMaskEditorStore()\n\n  const keysDown = ref<string[]>([])\n\n  const isKeyDown = (key: string): boolean => {\n    return keysDown.value.includes(key)\n  }\n\n  const clearKeys = (): void => {\n    keysDown.value = []\n  }\n\n  const handleKeyDown = (event: KeyboardEvent): void => {\n    if (!keysDown.value.includes(event.key)) {\n      keysDown.value.push(event.key)\n    }\n\n    if (event.key === ' ') {\n      event.preventDefault()\n      const activeElement = document.activeElement\n      if (activeElement instanceof HTMLElement) {\n        activeElement.blur()\n      }\n    }\n\n    if ((event.ctrlKey || event.metaKey) && !event.altKey) {\n      const key = event.key.toUpperCase()\n\n      if ((key === 'Y' && !event.shiftKey) || (key === 'Z' && event.shiftKey)) {\n        store.canvasHistory.redo()\n      } else if (key === 'Z' && !event.shiftKey) {\n        store.canvasHistory.undo()\n      }\n    }\n  }\n\n  const handleKeyUp = (event: KeyboardEvent): void => {\n    keysDown.value = keysDown.value.filter((key) => key !== event.key)\n  }\n\n  const addListeners = (): void => {\n    // Capture phase: the Mask Editor content root carries `@keydown.stop`\n    // (MaskEditorContent.vue), so a bubble-phase listener never sees keydowns\n    // that originate inside it. Under the Reka dialog the focus trap keeps\n    // focus on an in-editor input, so Ctrl+Z/Y (undo/redo) and the space-pan\n    // blur were swallowed. Capturing runs this before that stopPropagation.\n    document.addEventListener('keydown', handleKeyDown, true)\n    document.addEventListener('keyup', handleKeyUp)\n    window.addEventListener('blur', clearKeys)\n  }\n\n  const removeListeners = (): void => {\n    document.removeEventListener('keydown', handleKeyDown, true)\n    document.removeEventListener('keyup', handleKeyUp)\n    window.removeEventListener('blur', clearKeys)\n  }\n\n  return {\n    isKeyDown,\n    addListeners,\n    removeListeners\n  }\n}\n","import { IMAGE_WIDGET } from '@/composables/maskeditor/imageWidgetAdapter'\nimport { getNodeWidgetValue } from '@/core/graph/widgets/nodeWidgetValues'\nimport { useMaskEditorDataStore } from '@/stores/maskEditorDataStore'\nimport type { ImageRef, ImageLayer } from '@/stores/maskEditorDataStore'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { isCloud } from '@/platform/distribution/types'\nimport { api } from '@/scripts/api'\nimport { useApp } from '@/scripts/appInstance'\nimport { parseImageWidgetValue } from '@/utils/imageUtil'\n\nexport function extractWidgetStringValue(value: unknown): string | undefined {\n  if (typeof value === 'string') return value\n  if (\n    value &&\n    typeof value === 'object' &&\n    'filename' in value &&\n    typeof value.filename === 'string'\n  )\n    return value.filename\n  return undefined\n}\n\n// Private image utility functions\ninterface ImageLayerFilenames {\n  maskedImage: string\n  paint: string\n  paintedImage: string\n  paintedMaskedImage: string\n}\n\ninterface MaskLayersResponse {\n  painted_masked?: string\n  painted?: string\n  paint?: string\n  mask?: string\n}\n\nconst paintedMaskedImagePrefix = 'clipspace-painted-masked-'\n\nfunction imageLayerFilenamesIfApplicable(\n  inputImageFilename: string\n): ImageLayerFilenames | undefined {\n  const isPaintedMaskedImageFilename = inputImageFilename.startsWith(\n    paintedMaskedImagePrefix\n  )\n  if (!isPaintedMaskedImageFilename) return undefined\n  const suffix = inputImageFilename.slice(paintedMaskedImagePrefix.length)\n  const timestamp = parseInt(suffix.split('.')[0], 10)\n  return {\n    maskedImage: `clipspace-mask-${timestamp}.png`,\n    paint: `clipspace-paint-${timestamp}.png`,\n    paintedImage: `clipspace-painted-${timestamp}.png`,\n    paintedMaskedImage: `${paintedMaskedImagePrefix}${timestamp}.png`\n  }\n}\n\nfunction toRef(filename: string, subfolder: string): ImageRef {\n  return {\n    filename,\n    subfolder,\n    type: 'input'\n  }\n}\n\nfunction mkFileUrl(props: { ref: ImageRef; preview?: boolean }): string {\n  const params = new URLSearchParams()\n  params.set('filename', props.ref.filename)\n  if (props.ref.subfolder) {\n    params.set('subfolder', props.ref.subfolder)\n  }\n  if (props.ref.type) {\n    params.set('type', props.ref.type)\n  }\n\n  const pathPlusQueryParams = api.apiURL(\n    '/view?' +\n      params.toString() +\n      useApp().getPreviewFormatParam() +\n      useApp().getRandParam()\n  )\n  const imageElement = new Image()\n  imageElement.crossOrigin = 'anonymous'\n  imageElement.src = pathPlusQueryParams\n  return imageElement.src\n}\n\nexport function useMaskEditorLoader() {\n  const dataStore = useMaskEditorDataStore()\n  const nodeOutputStore = useNodeOutputStore()\n\n  const loadFromNode = async (node: LGraphNode): Promise<void> => {\n    dataStore.setLoading(true)\n\n    try {\n      validateNode(node)\n\n      let nodeImageUrl = getNodeImageUrl(node)\n\n      let nodeImageRef = parseImageRef(nodeImageUrl)\n\n      const widgetFilename = extractWidgetStringValue(\n        getNodeWidgetValue(node, IMAGE_WIDGET)\n      )\n\n      // If we have a widget filename, we should prioritize it over the node image\n      // because the node image might be stale (e.g. from a previous save)\n      // while the widget value reflects the current selection.\n      // Skip internal reference formats (e.g. \"$35-0\" used by some plugins like Impact-Pack)\n      if (widgetFilename && !widgetFilename.startsWith('$')) {\n        const parsed = parseImageWidgetValue(widgetFilename)\n        nodeImageRef = {\n          filename: parsed.filename,\n          type: parsed.type || 'input',\n          subfolder: parsed.subfolder || undefined\n        }\n        nodeImageUrl = mkFileUrl({ ref: nodeImageRef })\n      }\n\n      const fileToQuery = widgetFilename || nodeImageRef.filename\n\n      let maskLayersFromApi: MaskLayersResponse | undefined\n      if (isCloud) {\n        try {\n          const response = await api.fetchApi(\n            `/files/mask-layers?filename=${fileToQuery}`\n          )\n          if (response.ok) {\n            maskLayersFromApi = await response.json()\n          }\n        } catch {\n          // Fallback to pattern matching if API call fails\n        }\n      }\n\n      let imageLayerFilenames = imageLayerFilenamesIfApplicable(\n        nodeImageRef.filename\n      )\n\n      if (maskLayersFromApi) {\n        const baseFile =\n          maskLayersFromApi.painted_masked || maskLayersFromApi.painted\n\n        if (baseFile) {\n          imageLayerFilenames = {\n            maskedImage: baseFile,\n            paint: maskLayersFromApi.paint || '',\n            paintedImage: maskLayersFromApi.painted || '',\n            paintedMaskedImage: maskLayersFromApi.painted_masked || baseFile\n          }\n        }\n      }\n\n      // Pattern-matched layer files live next to the painted-masked image the\n      // widget points at: the input root for saves under the unified upload\n      // contract (#12318), or the clipspace subfolder for saves made before\n      // it. Cloud resolves the hash filenames from its mask-layers API\n      // server-side, so its refs keep the subfolder they always used.\n      const layerSubfolder = maskLayersFromApi\n        ? 'clipspace'\n        : (nodeImageRef.subfolder ?? '')\n\n      const layeredBaseUrl = imageLayerFilenames?.maskedImage\n        ? mkFileUrl({\n            ref: toRef(imageLayerFilenames.maskedImage, layerSubfolder)\n          })\n        : undefined\n      const baseImageUrl = layeredBaseUrl ?? nodeImageUrl\n\n      let paintLayerUrl: string | null = null\n      if (maskLayersFromApi?.paint) {\n        paintLayerUrl = mkFileUrl({\n          ref: toRef(maskLayersFromApi.paint, layerSubfolder)\n        })\n      } else if (imageLayerFilenames?.paint) {\n        paintLayerUrl = mkFileUrl({\n          ref: toRef(imageLayerFilenames.paint, layerSubfolder)\n        })\n      }\n\n      const loadLayers = (baseUrl: string, paintUrl: string | null) =>\n        Promise.all([\n          loadImageLayer(baseUrl, 'rgb'),\n          loadImageLayer(baseUrl, 'a'),\n          paintUrl ? loadPaintLayer(paintUrl) : Promise.resolve(undefined)\n        ])\n\n      const loadInputData = async () => {\n        try {\n          const [baseLayer, maskLayer, paintLayer] = await loadLayers(\n            baseImageUrl,\n            paintLayerUrl\n          )\n          return {\n            baseLayer,\n            maskLayer,\n            paintLayer,\n            sourceRef: layeredBaseUrl\n              ? parseImageRef(baseImageUrl)\n              : nodeImageRef\n          }\n        } catch (error) {\n          if (!layeredBaseUrl) throw error\n          console.warn(\n            '[MaskEditorLoader] Failed to load editor layer files, falling back to the node image',\n            error\n          )\n          const [baseLayer, maskLayer] = await loadLayers(nodeImageUrl, null)\n          return {\n            baseLayer,\n            maskLayer,\n            paintLayer: undefined,\n            sourceRef: nodeImageRef\n          }\n        }\n      }\n\n      dataStore.inputData = {\n        ...(await loadInputData()),\n        nodeId: node.id\n      }\n\n      dataStore.sourceNode = node\n      dataStore.setLoading(false)\n    } catch (error) {\n      const errorMessage =\n        error instanceof Error ? error.message : 'Failed to load from node'\n      console.error('[MaskEditorLoader]', errorMessage, error)\n      dataStore.setLoading(false, errorMessage)\n      throw error\n    }\n  }\n\n  function validateNode(node: LGraphNode): void {\n    const hasImages = node.imgs?.length || node.previewMediaType === 'image'\n    if (!hasImages) {\n      throw new Error('Node has no images')\n    }\n  }\n\n  function getNodeImageUrl(node: LGraphNode): string {\n    if (node.images?.[0]) {\n      const img = node.images[0]\n      const params = new URLSearchParams({\n        filename: img.filename,\n        type: img.type || 'output',\n        subfolder: img.subfolder || ''\n      })\n      return api.apiURL(`/view?${params.toString()}`)\n    }\n\n    const outputs = nodeOutputStore.getNodeOutputs(node)\n    if (outputs?.images?.[0]) {\n      const img = outputs.images[0]\n      if (!img.filename) {\n        throw new Error('nodeOutputStore image missing filename')\n      }\n\n      const params = new URLSearchParams()\n      params.set('filename', img.filename)\n      params.set('type', img.type || 'output')\n      params.set('subfolder', img.subfolder || '')\n      return api.apiURL(`/view?${params.toString()}`)\n    }\n\n    if (node.imgs?.length) {\n      const index = node.imageIndex ?? 0\n      const imgSrc = node.imgs[index].src\n\n      if (imgSrc && !imgSrc.startsWith('data:')) {\n        return imgSrc\n      }\n    }\n\n    throw new Error('Unable to get image URL from node')\n  }\n\n  function parseImageRef(url: string): ImageRef {\n    try {\n      const urlObj = new URL(url)\n      const filename = urlObj.searchParams.get('filename')\n\n      if (!filename) {\n        throw new Error('Image URL missing filename parameter')\n      }\n\n      return {\n        filename,\n        subfolder: urlObj.searchParams.get('subfolder') || undefined,\n        type: urlObj.searchParams.get('type') || undefined\n      }\n    } catch (error) {\n      try {\n        const urlObj = new URL(url, window.location.origin)\n        const filename = urlObj.searchParams.get('filename')\n\n        if (!filename) {\n          throw new Error('Image URL missing filename parameter', {\n            cause: error\n          })\n        }\n\n        return {\n          filename,\n          subfolder: urlObj.searchParams.get('subfolder') || undefined,\n          type: urlObj.searchParams.get('type') || undefined\n        }\n      } catch (e) {\n        throw new Error(`Invalid image URL: ${url}`, { cause: e })\n      }\n    }\n  }\n\n  async function loadImageLayer(\n    url: string,\n    channel?: 'rgb' | 'a'\n  ): Promise<ImageLayer> {\n    let urlObj: URL\n    try {\n      urlObj = new URL(url)\n    } catch {\n      urlObj = new URL(url, window.location.origin)\n    }\n\n    if (channel) {\n      urlObj.searchParams.delete('channel')\n      urlObj.searchParams.set('channel', channel)\n    }\n\n    const finalUrl = urlObj.toString()\n    const image = await loadImage(finalUrl)\n\n    return { image, url: finalUrl }\n  }\n\n  function loadImage(url: string): Promise<HTMLImageElement> {\n    return new Promise((resolve, reject) => {\n      const img = new Image()\n      img.crossOrigin = 'anonymous'\n\n      img.onload = () => resolve(img)\n      img.onerror = () => reject(new Error(`Failed to load image: ${url}`))\n\n      img.src = url\n    })\n  }\n\n  async function loadPaintLayer(url: string): Promise<ImageLayer> {\n    let urlObj: URL\n    try {\n      urlObj = new URL(url)\n    } catch {\n      urlObj = new URL(url, window.location.origin)\n    }\n\n    const finalUrl = urlObj.toString()\n    const image = await loadImage(finalUrl)\n\n    return { image, url: finalUrl }\n  }\n\n  return {\n    loadFromNode\n  }\n}\n","import type { Offset, Point } from '@/extensions/core/maskeditor/types'\n\nconst ZOOM_MIN = 0.2\nconst ZOOM_MAX = 10.0\n\ninterface FitViewParams {\n  rootWidth: number\n  rootHeight: number\n  imageWidth: number\n  imageHeight: number\n  toolPanelWidth: number\n  sidePanelWidth: number\n}\n\ninterface FitViewResult {\n  zoomRatio: number\n  panOffset: Offset\n  fittedWidth: number\n  fittedHeight: number\n}\n\nexport function calculateFitView(params: FitViewParams): FitViewResult {\n  const {\n    rootWidth,\n    rootHeight,\n    imageWidth,\n    imageHeight,\n    toolPanelWidth,\n    sidePanelWidth\n  } = params\n\n  const availableWidth = rootWidth - sidePanelWidth - toolPanelWidth\n  const availableHeight = rootHeight\n\n  const zoomRatioWidth = availableWidth / imageWidth\n  const zoomRatioHeight = availableHeight / imageHeight\n  const zoomRatio = Math.min(zoomRatioWidth, zoomRatioHeight)\n\n  const aspectRatio = imageWidth / imageHeight\n  const panOffset: Offset = { x: toolPanelWidth, y: 0 }\n\n  let fittedWidth: number\n  let fittedHeight: number\n\n  if (zoomRatioHeight > zoomRatioWidth) {\n    fittedWidth = availableWidth\n    fittedHeight = fittedWidth / aspectRatio\n    panOffset.y = (availableHeight - fittedHeight) / 2\n  } else {\n    fittedHeight = availableHeight\n    fittedWidth = fittedHeight * aspectRatio\n    panOffset.x = (availableWidth - fittedWidth) / 2 + toolPanelWidth\n  }\n\n  return { zoomRatio, panOffset, fittedWidth, fittedHeight }\n}\n\nexport function clampZoom(zoom: number): number {\n  return Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, zoom))\n}\n\nexport function getWheelZoomFactor(deltaY: number): number {\n  return deltaY < 0 ? 1.1 : 0.9\n}\n\nexport function calculateZoomAroundPoint(\n  currentZoom: number,\n  zoomFactor: number,\n  panOffset: Offset,\n  focalX: number,\n  focalY: number\n): { zoomRatio: number; panOffset: Offset } {\n  const newZoom = clampZoom(currentZoom * zoomFactor)\n  const scaleFactor = newZoom / currentZoom\n\n  return {\n    zoomRatio: newZoom,\n    panOffset: {\n      x: panOffset.x + focalX - focalX * scaleFactor,\n      y: panOffset.y + focalY - focalY * scaleFactor\n    }\n  }\n}\n\nexport function calculateDragPan(\n  mouseDownPoint: Point,\n  currentPoint: Point,\n  initialPan: Offset\n): Offset {\n  return {\n    x: initialPan.x - (mouseDownPoint.x - currentPoint.x),\n    y: initialPan.y - (mouseDownPoint.y - currentPoint.y)\n  }\n}\n\nexport function calculateSingleTouchPan(\n  lastPoint: Point,\n  currentPoint: Point,\n  panOffset: Offset\n): Offset {\n  return {\n    x: panOffset.x + (currentPoint.x - lastPoint.x),\n    y: panOffset.y + (currentPoint.y - lastPoint.y)\n  }\n}\n\nexport function getDistanceBetweenPoints(a: Point, b: Point): number {\n  const dx = a.x - b.x\n  const dy = a.y - b.y\n  return Math.sqrt(dx * dx + dy * dy)\n}\n\nexport function getMidpoint(a: Point, b: Point): Point {\n  return {\n    x: (a.x + b.x) / 2,\n    y: (a.y + b.y) / 2\n  }\n}\n\nexport function getCursorPoint(clientPoint: Point, panOffset: Offset): Point {\n  return {\n    x: clientPoint.x - panOffset.x,\n    y: clientPoint.y - panOffset.y\n  }\n}\n\nexport function isDoubleTap(\n  currentTime: number,\n  lastTapTime: number,\n  delay: number\n): boolean {\n  return currentTime - lastTapTime < delay\n}\n\nexport function easeOutCubic(progress: number): number {\n  return 1 - Math.pow(1 - progress, 3)\n}\n\nexport function interpolateView(\n  startZoom: number,\n  targetZoom: number,\n  startPan: Offset,\n  targetPan: Offset,\n  easedProgress: number\n): { zoomRatio: number; panOffset: Offset } {\n  return {\n    zoomRatio: startZoom + (targetZoom - startZoom) * easedProgress,\n    panOffset: {\n      x: startPan.x + (targetPan.x - startPan.x) * easedProgress,\n      y: startPan.y + (targetPan.y - startPan.y) * easedProgress\n    }\n  }\n}\n\nexport function calculatePanZoomStyles(\n  imageWidth: number,\n  imageHeight: number,\n  zoomRatio: number,\n  panOffset: Offset\n): {\n  rawWidth: number\n  rawHeight: number\n  containerLeft: string\n  containerTop: string\n  containerWidth: string\n  containerHeight: string\n} {\n  const rawWidth = imageWidth * zoomRatio\n  const rawHeight = imageHeight * zoomRatio\n  return {\n    rawWidth,\n    rawHeight,\n    containerLeft: `${panOffset.x}px`,\n    containerTop: `${panOffset.y}px`,\n    containerWidth: `${rawWidth}px`,\n    containerHeight: `${rawHeight}px`\n  }\n}\n","import { ref, watch } from 'vue'\n\nimport type { Offset, Point } from '@/extensions/core/maskeditor/types'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\n\nimport {\n  calculateDragPan,\n  calculateFitView,\n  calculatePanZoomStyles,\n  calculateSingleTouchPan,\n  calculateZoomAroundPoint,\n  easeOutCubic,\n  getCursorPoint,\n  getDistanceBetweenPoints,\n  getMidpoint,\n  getWheelZoomFactor,\n  interpolateView,\n  isDoubleTap\n} from './panZoomUtils'\n\nexport function usePanAndZoom() {\n  const store = useMaskEditorStore()\n\n  const DOUBLE_TAP_DELAY = 300\n\n  const lastTwoFingerTap = ref(0)\n  const isTouchZooming = ref(false)\n  const lastTouchZoomDistance = ref(0)\n  const lastTouchMidPoint = ref<Point>({ x: 0, y: 0 })\n  const lastTouchPoint = ref<Point>({ x: 0, y: 0 })\n\n  const zoom_ratio = ref(1)\n  const interpolatedZoomRatio = ref(1)\n  const pan_offset = ref<Offset>({ x: 0, y: 0 })\n\n  const mouseDownPoint = ref<Point | null>(null)\n  const initialPan = ref<Offset>({ x: 0, y: 0 })\n\n  const canvasContainer = ref<HTMLElement | null>(null)\n  const maskCanvas = ref<HTMLCanvasElement | null>(null)\n  const rgbCanvas = ref<HTMLCanvasElement | null>(null)\n  const rootElement = ref<HTMLElement | null>(null)\n\n  const toolPanelElement = ref<HTMLElement | null>(null)\n  const sidePanelElement = ref<HTMLElement | null>(null)\n\n  const image = ref<HTMLImageElement | null>(null)\n  const imageRootWidth = ref(0)\n  const imageRootHeight = ref(0)\n\n  const cursorPoint = ref<Point>({ x: 0, y: 0 })\n  const penPointerIdList = ref<number[]>([])\n\n  const updateCursorPosition = (clientPoint: Point): void => {\n    const point = getCursorPoint(clientPoint, pan_offset.value)\n    cursorPoint.value = point\n    store.setCursorPoint(point)\n  }\n\n  const handleDoubleTap = (): void => {\n    store.canvasHistory.undo()\n  }\n\n  const invalidatePanZoom = async (): Promise<void> => {\n    const currentImage = image.value\n    if (!currentImage?.width || !currentImage.height || !zoom_ratio.value) {\n      console.warn('Missing required properties for pan/zoom')\n      return\n    }\n\n    const styles = calculatePanZoomStyles(\n      currentImage.width,\n      currentImage.height,\n      zoom_ratio.value,\n      pan_offset.value\n    )\n\n    if (!canvasContainer.value) {\n      canvasContainer.value = store.canvasContainer\n    }\n    if (!canvasContainer.value) return\n\n    Object.assign(canvasContainer.value.style, {\n      width: styles.containerWidth,\n      height: styles.containerHeight,\n      left: styles.containerLeft,\n      top: styles.containerTop\n    })\n\n    if (!rgbCanvas.value) {\n      rgbCanvas.value = store.rgbCanvas\n    }\n    if (rgbCanvas.value) {\n      if (\n        rgbCanvas.value.width !== currentImage.width ||\n        rgbCanvas.value.height !== currentImage.height\n      ) {\n        rgbCanvas.value.width = currentImage.width\n        rgbCanvas.value.height = currentImage.height\n      }\n\n      rgbCanvas.value.style.width = styles.containerWidth\n      rgbCanvas.value.style.height = styles.containerHeight\n    }\n\n    store.setPanOffset(pan_offset.value)\n    store.setZoomRatio(zoom_ratio.value)\n  }\n\n  const handlePanStart = (event: PointerEvent): void => {\n    mouseDownPoint.value = { x: event.clientX, y: event.clientY }\n\n    store.isPanning = true\n    initialPan.value = { ...pan_offset.value }\n  }\n\n  const handlePanMove = async (event: PointerEvent): Promise<void> => {\n    if (mouseDownPoint.value === null) {\n      console.error('mouseDownPoint is null')\n      return\n    }\n\n    pan_offset.value = calculateDragPan(\n      mouseDownPoint.value,\n      { x: event.clientX, y: event.clientY },\n      initialPan.value\n    )\n\n    await invalidatePanZoom()\n  }\n\n  const handleSingleTouchPan = async (touch: Touch): Promise<void> => {\n    pan_offset.value = calculateSingleTouchPan(\n      lastTouchPoint.value,\n      { x: touch.clientX, y: touch.clientY },\n      pan_offset.value\n    )\n\n    await invalidatePanZoom()\n\n    lastTouchPoint.value = { x: touch.clientX, y: touch.clientY }\n  }\n\n  const touchToPoint = (touch: Touch): Point => ({\n    x: touch.clientX,\n    y: touch.clientY\n  })\n\n  const handleTouchStart = (event: TouchEvent): void => {\n    event.preventDefault()\n\n    if (penPointerIdList.value.length > 0) return\n\n    store.brushVisible = false\n\n    if (event.touches.length === 2) {\n      const currentTime = new Date().getTime()\n\n      if (isDoubleTap(currentTime, lastTwoFingerTap.value, DOUBLE_TAP_DELAY)) {\n        handleDoubleTap()\n        lastTwoFingerTap.value = 0\n      } else {\n        lastTwoFingerTap.value = currentTime\n\n        const p0 = touchToPoint(event.touches[0])\n        const p1 = touchToPoint(event.touches[1])\n\n        isTouchZooming.value = true\n        lastTouchZoomDistance.value = getDistanceBetweenPoints(p0, p1)\n        lastTouchMidPoint.value = getMidpoint(p0, p1)\n      }\n    } else if (event.touches.length === 1) {\n      lastTouchPoint.value = touchToPoint(event.touches[0])\n    }\n  }\n\n  const handleTouchMove = async (event: TouchEvent): Promise<void> => {\n    event.preventDefault()\n\n    if (penPointerIdList.value.length > 0) return\n\n    lastTwoFingerTap.value = 0\n\n    if (isTouchZooming.value && event.touches.length === 2) {\n      const p0 = touchToPoint(event.touches[0])\n      const p1 = touchToPoint(event.touches[1])\n\n      const newDistance = getDistanceBetweenPoints(p0, p1)\n      const pinchFactor = newDistance / lastTouchZoomDistance.value\n      const midpoint = getMidpoint(p0, p1)\n\n      // Apply midpoint drag\n      const draggedPan: Offset = {\n        x: pan_offset.value.x + midpoint.x - lastTouchMidPoint.value.x,\n        y: pan_offset.value.y + midpoint.y - lastTouchMidPoint.value.y\n      }\n\n      if (!maskCanvas.value) {\n        maskCanvas.value = store.maskCanvas\n      }\n      if (!maskCanvas.value) return\n\n      const rect = maskCanvas.value.getBoundingClientRect()\n      const focalX = midpoint.x - rect.left\n      const focalY = midpoint.y - rect.top\n\n      const result = calculateZoomAroundPoint(\n        zoom_ratio.value,\n        pinchFactor,\n        draggedPan,\n        focalX,\n        focalY\n      )\n\n      zoom_ratio.value = result.zoomRatio\n      pan_offset.value = result.panOffset\n\n      await invalidatePanZoom()\n      lastTouchZoomDistance.value = newDistance\n      lastTouchMidPoint.value = midpoint\n    } else if (event.touches.length === 1) {\n      await handleSingleTouchPan(event.touches[0])\n    }\n  }\n\n  const handleTouchEnd = (event: TouchEvent): void => {\n    event.preventDefault()\n\n    if (event.touches.length > 0) {\n      lastTouchPoint.value = touchToPoint(event.touches[0])\n    } else {\n      isTouchZooming.value = false\n      lastTouchMidPoint.value = { x: 0, y: 0 }\n    }\n  }\n\n  const zoom = async (event: WheelEvent): Promise<void> => {\n    const cursorPosition = { x: event.clientX, y: event.clientY }\n\n    if (!maskCanvas.value) {\n      maskCanvas.value = store.maskCanvas\n    }\n    if (!maskCanvas.value) return\n\n    const rect = maskCanvas.value.getBoundingClientRect()\n    const focalX = cursorPosition.x - rect.left\n    const focalY = cursorPosition.y - rect.top\n\n    const result = calculateZoomAroundPoint(\n      zoom_ratio.value,\n      getWheelZoomFactor(event.deltaY),\n      pan_offset.value,\n      focalX,\n      focalY\n    )\n\n    zoom_ratio.value = result.zoomRatio\n    pan_offset.value = result.panOffset\n\n    await invalidatePanZoom()\n\n    const newImageWidth = maskCanvas.value.clientWidth\n    const zoomRatio = newImageWidth / imageRootWidth.value\n\n    interpolatedZoomRatio.value = zoomRatio\n    store.displayZoomRatio = zoomRatio\n\n    updateCursorPosition(cursorPosition)\n  }\n\n  const getPanelDimensions = (): {\n    sidePanelWidth: number\n    toolPanelWidth: number\n  } => {\n    const toolPanelWidth =\n      toolPanelElement.value?.getBoundingClientRect().width || 64\n    const sidePanelWidth =\n      sidePanelElement.value?.getBoundingClientRect().width || 220\n\n    return { sidePanelWidth, toolPanelWidth }\n  }\n\n  const smoothResetView = async (duration: number = 500): Promise<void> => {\n    if (!image.value || !rootElement.value) return\n\n    const startZoom = zoom_ratio.value\n    const startPan = { ...pan_offset.value }\n\n    const { sidePanelWidth, toolPanelWidth } = getPanelDimensions()\n\n    const fitResult = calculateFitView({\n      rootWidth: rootElement.value.clientWidth,\n      rootHeight: rootElement.value.clientHeight,\n      imageWidth: image.value.width,\n      imageHeight: image.value.height,\n      toolPanelWidth,\n      sidePanelWidth\n    })\n\n    const startTime = performance.now()\n    const animate = async (currentTime: number) => {\n      const elapsed = currentTime - startTime\n      const progress = Math.min(elapsed / duration, 1)\n      const eased = easeOutCubic(progress)\n\n      const frame = interpolateView(\n        startZoom,\n        fitResult.zoomRatio,\n        startPan,\n        fitResult.panOffset,\n        eased\n      )\n\n      zoom_ratio.value = frame.zoomRatio\n      pan_offset.value = frame.panOffset\n\n      await invalidatePanZoom()\n\n      const interpolatedRatio = startZoom + (1.0 - startZoom) * eased\n      store.displayZoomRatio = interpolatedRatio\n\n      if (progress < 1) {\n        requestAnimationFrame(animate)\n      }\n    }\n\n    requestAnimationFrame(animate)\n    interpolatedZoomRatio.value = 1.0\n  }\n\n  const initializeCanvasPanZoom = async (\n    img: HTMLImageElement,\n    root: HTMLElement,\n    toolPanel?: HTMLElement | null,\n    sidePanel?: HTMLElement | null\n  ): Promise<void> => {\n    rootElement.value = root\n    toolPanelElement.value = toolPanel || null\n    sidePanelElement.value = sidePanel || null\n\n    const { sidePanelWidth, toolPanelWidth } = getPanelDimensions()\n\n    const fitResult = calculateFitView({\n      rootWidth: root.clientWidth,\n      rootHeight: root.clientHeight,\n      imageWidth: img.width,\n      imageHeight: img.height,\n      toolPanelWidth,\n      sidePanelWidth\n    })\n\n    if (image.value === null) {\n      image.value = img\n    }\n\n    imageRootWidth.value = fitResult.fittedWidth\n    imageRootHeight.value = fitResult.fittedHeight\n\n    zoom_ratio.value = fitResult.zoomRatio\n    pan_offset.value = fitResult.panOffset\n\n    penPointerIdList.value = []\n\n    await invalidatePanZoom()\n  }\n\n  watch(\n    () => store.resetZoomTrigger,\n    async () => {\n      if (interpolatedZoomRatio.value === 1) return\n      await smoothResetView()\n    }\n  )\n\n  const addPenPointerId = (pointerId: number): void => {\n    if (!penPointerIdList.value.includes(pointerId)) {\n      penPointerIdList.value.push(pointerId)\n    }\n  }\n\n  const removePenPointerId = (pointerId: number): void => {\n    const index = penPointerIdList.value.indexOf(pointerId)\n    if (index !== -1) {\n      penPointerIdList.value.splice(index, 1)\n    }\n  }\n\n  return {\n    initializeCanvasPanZoom,\n    handlePanStart,\n    handlePanMove,\n    handleTouchStart,\n    handleTouchMove,\n    handleTouchEnd,\n    updateCursorPosition,\n    zoom,\n    invalidatePanZoom,\n    addPenPointerId,\n    removePenPointerId\n  }\n}\n","import QuickLRU from '@alloc/quick-lru'\n\nimport { hexToRgb, parseToRgb } from '@/utils/colorUtil'\nimport { BrushShape } from '@/extensions/core/maskeditor/types'\nimport type { Point } from '@/extensions/core/maskeditor/types'\n\nexport type DirtyRect = {\n  minX: number\n  minY: number\n  maxX: number\n  maxY: number\n}\n\ntype MaskColor = { r: number; g: number; b: number }\n\nconst brushTextureCache = new QuickLRU<string, HTMLCanvasElement>({\n  maxSize: 20\n})\n\nexport function resetDirtyRect(): DirtyRect {\n  return { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity }\n}\n\nexport function updateDirtyRect(\n  rect: DirtyRect,\n  x: number,\n  y: number,\n  radius: number\n): DirtyRect {\n  const padding = 2\n  return {\n    minX: Math.min(rect.minX, x - radius - padding),\n    minY: Math.min(rect.minY, y - radius - padding),\n    maxX: Math.max(rect.maxX, x + radius + padding),\n    maxY: Math.max(rect.maxY, y + radius + padding)\n  }\n}\n\nfunction formatRgba(hex: string, alpha: number): string {\n  const { r, g, b } = hexToRgb(hex)\n  return `rgba(${r}, ${g}, ${b}, ${alpha})`\n}\n\nexport function premultiplyData(data: Uint8ClampedArray): void {\n  for (let i = 0; i < data.length; i += 4) {\n    const a = data[i + 3] / 255\n    data[i] = Math.round(data[i] * a)\n    data[i + 1] = Math.round(data[i + 1] * a)\n    data[i + 2] = Math.round(data[i + 2] * a)\n  }\n}\n\nfunction drawShapeOnContext(\n  ctx: CanvasRenderingContext2D,\n  brushType: BrushShape,\n  x: number,\n  y: number,\n  radius: number\n): void {\n  ctx.beginPath()\n  if (brushType === BrushShape.Rect) {\n    ctx.rect(x - radius, y - radius, radius * 2, radius * 2)\n  } else {\n    ctx.arc(x, y, radius, 0, Math.PI * 2, false)\n  }\n  ctx.fill()\n}\n\nfunction createBrushGradient(\n  ctx: CanvasRenderingContext2D,\n  x: number,\n  y: number,\n  radius: number,\n  hardness: number,\n  color: string,\n  opacity: number,\n  isErasing: boolean\n): CanvasGradient {\n  if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(radius)) {\n    return ctx.createRadialGradient(0, 0, 0, 0, 0, 0)\n  }\n\n  const gradient = ctx.createRadialGradient(x, y, 0, x, y, radius)\n\n  if (isErasing) {\n    gradient.addColorStop(0, `rgba(255, 255, 255, ${opacity})`)\n    gradient.addColorStop(hardness, `rgba(255, 255, 255, ${opacity})`)\n    gradient.addColorStop(1, `rgba(255, 255, 255, 0)`)\n  } else {\n    const { r, g, b } = parseToRgb(color)\n    gradient.addColorStop(0, `rgba(${r}, ${g}, ${b}, ${opacity})`)\n    gradient.addColorStop(hardness, `rgba(${r}, ${g}, ${b}, ${opacity})`)\n    gradient.addColorStop(1, `rgba(${r}, ${g}, ${b}, 0)`)\n  }\n\n  return gradient\n}\n\nfunction getCachedBrushTexture(\n  radius: number,\n  hardness: number,\n  color: string,\n  opacity: number\n): HTMLCanvasElement {\n  const cacheKey = `${radius}_${hardness}_${color}`\n  const cached = brushTextureCache.get(cacheKey)\n  if (cached) return cached\n\n  const size = Math.max(1, Math.ceil(radius * 2))\n  if (!Number.isFinite(size)) {\n    throw new Error(`Invalid brush radius: ${radius}`)\n  }\n\n  const tempCanvas = document.createElement('canvas')\n  tempCanvas.width = size\n  tempCanvas.height = size\n  const tempCtx = tempCanvas.getContext('2d')\n  if (!tempCtx) {\n    throw new Error('Unable to create 2D canvas context for brush texture')\n  }\n\n  const centerX = size / 2\n  const centerY = size / 2\n  const hardRadius = radius * hardness\n  const imageData = tempCtx.createImageData(size, size)\n  const data = imageData.data\n  const { r, g, b } = parseToRgb(color)\n  const fadeRange = radius - hardRadius\n\n  for (let y = 0; y < size; y++) {\n    const dy = y + 0.5 - centerY\n    for (let x = 0; x < size; x++) {\n      const dx = x + 0.5 - centerX\n      const index = (y * size + x) * 4\n      const distFromEdge = Math.max(Math.abs(dx), Math.abs(dy))\n\n      let pixelOpacity = 0\n      if (distFromEdge <= hardRadius) {\n        pixelOpacity = opacity\n      } else if (distFromEdge <= radius) {\n        const fadeProgress = (distFromEdge - hardRadius) / fadeRange\n        pixelOpacity = opacity * Math.pow(1 - fadeProgress, 2)\n      }\n\n      data[index] = r\n      data[index + 1] = g\n      data[index + 2] = b\n      data[index + 3] = pixelOpacity * 255\n    }\n  }\n\n  tempCtx.putImageData(imageData, 0, 0)\n  brushTextureCache.set(cacheKey, tempCanvas)\n  return tempCanvas\n}\n\nexport function drawRgbShape(\n  ctx: CanvasRenderingContext2D,\n  point: Point,\n  brushType: BrushShape,\n  brushRadius: number,\n  hardness: number,\n  opacity: number,\n  rgbColor: string\n): void {\n  const { x, y } = point\n\n  if (brushType === BrushShape.Rect && hardness < 1) {\n    const rgbaColor = formatRgba(rgbColor, opacity)\n    const brushTexture = getCachedBrushTexture(\n      brushRadius,\n      hardness,\n      rgbaColor,\n      opacity\n    )\n    ctx.drawImage(brushTexture, x - brushRadius, y - brushRadius)\n    return\n  }\n\n  if (hardness === 1) {\n    ctx.fillStyle = formatRgba(rgbColor, opacity)\n    drawShapeOnContext(ctx, brushType, x, y, brushRadius)\n    return\n  }\n\n  const gradient = createBrushGradient(\n    ctx,\n    x,\n    y,\n    brushRadius,\n    hardness,\n    rgbColor,\n    opacity,\n    false\n  )\n  ctx.fillStyle = gradient\n  drawShapeOnContext(ctx, brushType, x, y, brushRadius)\n}\n\nexport function drawMaskShape(\n  ctx: CanvasRenderingContext2D,\n  point: Point,\n  brushType: BrushShape,\n  brushRadius: number,\n  hardness: number,\n  opacity: number,\n  isErasing: boolean,\n  maskColor: MaskColor\n): void {\n  const { x, y } = point\n\n  if (brushType === BrushShape.Rect && hardness < 1) {\n    const baseColor = isErasing\n      ? `rgba(255, 255, 255, ${opacity})`\n      : `rgba(${maskColor.r}, ${maskColor.g}, ${maskColor.b}, ${opacity})`\n    const brushTexture = getCachedBrushTexture(\n      brushRadius,\n      hardness,\n      baseColor,\n      opacity\n    )\n    ctx.drawImage(brushTexture, x - brushRadius, y - brushRadius)\n    return\n  }\n\n  if (hardness === 1) {\n    ctx.fillStyle = isErasing\n      ? `rgba(255, 255, 255, ${opacity})`\n      : `rgba(${maskColor.r}, ${maskColor.g}, ${maskColor.b}, ${opacity})`\n    drawShapeOnContext(ctx, brushType, x, y, brushRadius)\n    return\n  }\n\n  const maskColorHex = `rgb(${maskColor.r}, ${maskColor.g}, ${maskColor.b})`\n  const gradient = createBrushGradient(\n    ctx,\n    x,\n    y,\n    brushRadius,\n    hardness,\n    maskColorHex,\n    opacity,\n    isErasing\n  )\n  ctx.fillStyle = gradient\n  drawShapeOnContext(ctx, brushType, x, y, brushRadius)\n}\n","import { createSharedComposable } from '@vueuse/core'\nimport { unref } from 'vue'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\n\ninterface Point {\n  x: number\n  y: number\n}\n\nfunction useCoordinateTransformInternal() {\n  const store = useMaskEditorStore()\n\n  const screenToCanvas = (clientPoint: Point): Point => {\n    const pointerZoneEl = unref(store.pointerZone)\n    const canvasContainerEl = unref(store.canvasContainer)\n    const canvasEl = unref(store.maskCanvas)\n\n    if (!pointerZoneEl || !canvasContainerEl || !canvasEl) {\n      console.warn('screenToCanvas called before elements are available')\n      return { x: 0, y: 0 }\n    }\n\n    const pointerZoneRect = pointerZoneEl.getBoundingClientRect()\n    const canvasContainerRect = canvasContainerEl.getBoundingClientRect()\n    const canvasRect = canvasEl.getBoundingClientRect()\n\n    const absoluteX = pointerZoneRect.left + clientPoint.x\n    const absoluteY = pointerZoneRect.top + clientPoint.y\n\n    const canvasX = absoluteX - canvasContainerRect.left\n    const canvasY = absoluteY - canvasContainerRect.top\n\n    const scaleX = canvasEl.width / canvasRect.width\n    const scaleY = canvasEl.height / canvasRect.height\n\n    const x = canvasX * scaleX\n    const y = canvasY * scaleY\n\n    return { x, y }\n  }\n\n  const canvasToScreen = (canvasPoint: Point): Point => {\n    const pointerZoneEl = unref(store.pointerZone)\n    const canvasContainerEl = unref(store.canvasContainer)\n    const canvasEl = unref(store.maskCanvas)\n\n    if (!pointerZoneEl || !canvasContainerEl || !canvasEl) {\n      console.warn('canvasToScreen called before elements are available')\n      return { x: 0, y: 0 }\n    }\n\n    const pointerZoneRect = pointerZoneEl.getBoundingClientRect()\n    const canvasContainerRect = canvasContainerEl.getBoundingClientRect()\n    const canvasRect = canvasEl.getBoundingClientRect()\n\n    const scaleX = canvasRect.width / canvasEl.width\n    const scaleY = canvasRect.height / canvasEl.height\n\n    const displayX = canvasPoint.x * scaleX\n    const displayY = canvasPoint.y * scaleY\n\n    const absoluteX = canvasContainerRect.left + displayX\n    const absoluteY = canvasContainerRect.top + displayY\n\n    const x = absoluteX - pointerZoneRect.left\n    const y = absoluteY - pointerZoneRect.top\n\n    return { x, y }\n  }\n\n  return {\n    screenToCanvas,\n    canvasToScreen\n  }\n}\n\nexport const useCoordinateTransform = createSharedComposable(\n  useCoordinateTransformInternal\n)\n","import { ref } from 'vue'\n\nimport type { Point } from '@/extensions/core/maskeditor/types'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\nimport { useCoordinateTransform } from './useCoordinateTransform'\n\nexport function useBrushAdjustment(initialSettings?: {\n  useDominantAxis?: boolean\n  brushAdjustmentSpeed?: number\n}) {\n  const store = useMaskEditorStore()\n  const coordinateTransform = useCoordinateTransform()\n\n  const initialPoint = ref<Point | null>(null)\n  const initialBrushSize = ref(0)\n  const initialBrushHardness = ref(0)\n  const useDominantAxis = ref(initialSettings?.useDominantAxis ?? false)\n  const brushAdjustmentSpeed = ref(initialSettings?.brushAdjustmentSpeed ?? 1.0)\n\n  async function startBrushAdjustment(event: PointerEvent): Promise<void> {\n    event.preventDefault()\n\n    const coords = { x: event.offsetX, y: event.offsetY }\n    const coords_canvas = coordinateTransform.screenToCanvas(coords)\n\n    store.brushPreviewGradientVisible = true\n    initialPoint.value = coords_canvas\n    initialBrushSize.value = store.brushSettings.size\n    initialBrushHardness.value = store.brushSettings.hardness\n  }\n\n  async function handleBrushAdjustment(event: PointerEvent): Promise<void> {\n    if (!initialPoint.value) {\n      return\n    }\n\n    const coords = { x: event.offsetX, y: event.offsetY }\n    const brushDeadZone = 5\n    const coords_canvas = coordinateTransform.screenToCanvas(coords)\n\n    const delta_x = coords_canvas.x - initialPoint.value.x\n    const delta_y = coords_canvas.y - initialPoint.value.y\n\n    const effectiveDeltaX = Math.abs(delta_x) < brushDeadZone ? 0 : delta_x\n    const effectiveDeltaY = Math.abs(delta_y) < brushDeadZone ? 0 : delta_y\n\n    let finalDeltaX = effectiveDeltaX\n    let finalDeltaY = effectiveDeltaY\n\n    if (useDominantAxis.value) {\n      const ratio = Math.abs(effectiveDeltaX) / Math.abs(effectiveDeltaY)\n      const threshold = 2.0\n\n      if (ratio > threshold) {\n        finalDeltaY = 0\n      } else if (ratio < 1 / threshold) {\n        finalDeltaX = 0\n      }\n    }\n\n    const newSize = Math.max(\n      1,\n      Math.min(\n        500,\n        initialBrushSize.value + (finalDeltaX / 35) * brushAdjustmentSpeed.value\n      )\n    )\n\n    const newHardness = Math.max(\n      0,\n      Math.min(\n        1,\n        initialBrushHardness.value -\n          (finalDeltaY / 4000) * brushAdjustmentSpeed.value\n      )\n    )\n\n    store.setBrushSize(newSize)\n    store.setBrushHardness(newHardness)\n  }\n\n  return { startBrushAdjustment, handleBrushAdjustment }\n}\n","import * as d from 'typegpu/data'\n\n// Global brush uniforms\nexport const BrushUniforms = d.struct({\n  brushColor: d.vec3f,\n  brushOpacity: d.f32,\n  hardness: d.f32,\n  screenSize: d.vec2f,\n  brushShape: d.u32 // 0: Circle, 1: Square\n})\n\n// Per-point instance data\nexport const StrokePoint = d.struct({\n  pos: d.location(0, d.vec2f), // Center position\n  size: d.location(1, d.f32), // Brush radius\n  pressure: d.location(2, d.f32) // Pressure value (0.0 - 1.0)\n})\n","import { tgpu } from 'typegpu'\nimport * as d from 'typegpu/data'\nimport { BrushUniforms } from './gpuSchema'\n\nconst VertexOutput = d.struct({\n  position: d.builtin.position,\n  localUV: d.location(0, d.vec2f),\n  color: d.location(1, d.vec3f),\n  opacity: d.location(2, d.f32),\n  hardness: d.location(3, d.f32)\n})\n\nconst brushVertexTemplate = `\n@group(0) @binding(0) var<uniform> globals: BrushUniforms;\n\n@vertex\nfn vs(\n  @location(0) quadPos: vec2<f32>,\n  @location(1) pos: vec2<f32>,\n  @location(2) size: f32,\n  @location(3) pressure: f32\n) -> VertexOutput {\n  // Convert diameter to radius\n  let radius = size * pressure;\n  let pixelPos = pos + (quadPos * radius);\n  \n  // Convert pixel coordinates to Normalized Device Coordinates (NDC)\n  let ndcX = (pixelPos.x / globals.screenSize.x) * 2.0 - 1.0;\n  let ndcY = 1.0 - ((pixelPos.y / globals.screenSize.y) * 2.0);  // Flip Y axis for WebGPU coordinate system\n\n  return VertexOutput(\n    vec4<f32>(ndcX, ndcY, 0.0, 1.0),\n    quadPos,\n    globals.brushColor,\n    pressure * globals.brushOpacity,\n    globals.hardness\n  );\n}\n`\n\nexport const brushVertex = tgpu.resolve({\n  template: brushVertexTemplate,\n  externals: {\n    BrushUniforms,\n    VertexOutput\n  }\n})\n\nconst brushFragmentTemplate = `\n@group(0) @binding(0) var<uniform> globals: BrushUniforms;\n\n@fragment\nfn fs(v: VertexOutput) -> @location(0) vec4<f32> {\n  var dist: f32;\n  if (globals.brushShape == 1u) {\n    // Calculate Chebyshev distance for square shape\n    dist = max(abs(v.localUV.x), abs(v.localUV.y));\n  } else {\n    // Calculate Euclidean distance for circle shape\n    dist = length(v.localUV);\n  }\n\n  if (dist > 1.0) { discard; }\n\n  // Calculate alpha with hardness and anti-aliasing\n  let edgeWidth = fwidth(dist);\n  let startFade = min(v.hardness, 1.0 - edgeWidth * 2.0);\n  let linearAlpha = 1.0 - smoothstep(startFade, 1.0, dist);\n  // Apply quadratic falloff for smoother edges\n  let alphaShape = pow(linearAlpha, 2.0);\n  \n  // Return premultiplied alpha color\n  let alpha = alphaShape * v.opacity;\n  return vec4<f32>(v.color * alpha, alpha);\n}\n`\n\nexport const brushFragment = tgpu.resolve({\n  template: brushFragmentTemplate,\n  externals: {\n    VertexOutput,\n    BrushUniforms\n  }\n})\n\nconst blitShaderTemplate = `\n@vertex fn vs(@builtin(vertex_index) vIdx: u32) -> @builtin(position) vec4<f32> {\n  var pos = array<vec2<f32>, 3>(\n    vec2<f32>(-1.0, -1.0), vec2<f32>(3.0, -1.0), vec2<f32>(-1.0, 3.0)\n  );\n  return vec4<f32>(pos[vIdx], 0.0, 1.0);\n}\n\n@group(0) @binding(0) var myTexture: texture_2d<f32>;\n\n@fragment fn fs(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {\n  let c = textureLoad(myTexture, vec2<i32>(pos.xy), 0);\n  // Treat texture as premultiplied to prevent double-darkening on overlaps\n  return c;\n}\n`\n\nexport const blitShader = tgpu.resolve({\n  template: blitShaderTemplate,\n  externals: {}\n})\n\nconst compositeShaderTemplate = `\n@vertex fn vs(@builtin(vertex_index) vIdx: u32) -> @builtin(position) vec4<f32> {\n  var pos = array<vec2<f32>, 3>(\n    vec2<f32>(-1.0, -1.0), vec2<f32>(3.0, -1.0), vec2<f32>(-1.0, 3.0)\n  );\n  return vec4<f32>(pos[vIdx], 0.0, 1.0);\n}\n\n@group(0) @binding(0) var myTexture: texture_2d<f32>;\n@group(1) @binding(0) var<uniform> globals: BrushUniforms;\n\n@fragment fn fs(@builtin(position) pos: vec4<f32>) -> @location(0) vec4<f32> {\n  let sampled = textureLoad(myTexture, vec2<i32>(pos.xy), 0);\n  // Apply global brush opacity to accumulated coverage\n  return sampled * globals.brushOpacity;\n}\n`\n\nexport const compositeShader = tgpu.resolve({\n  template: compositeShaderTemplate,\n  externals: {\n    BrushUniforms\n  }\n})\n\nconst readbackShaderTemplate = `\n@group(0) @binding(0) var inputTex: texture_2d<f32>;\n@group(0) @binding(1) var<storage, read_write> outputBuf: array<u32>;\n\n@compute @workgroup_size(8, 8)\nfn main(@builtin(global_invocation_id) id: vec3<u32>) {\n  let dims = textureDimensions(inputTex);\n  if (id.x >= dims.x || id.y >= dims.y) { return; }\n\n  let color = textureLoad(inputTex, vec2<i32>(id.xy), 0);\n  \n  var r = color.r;\n  var g = color.g;\n  var b = color.b;\n  let a = color.a;\n\n  if (a > 0.0) {\n    r = r / a;\n    g = g / a;\n    b = b / a;\n  }\n\n  let ir = u32(clamp(r * 255.0 + 0.5, 0.0, 255.0));\n  let ig = u32(clamp(g * 255.0 + 0.5, 0.0, 255.0));\n  let ib = u32(clamp(b * 255.0 + 0.5, 0.0, 255.0));\n  let ia = u32(clamp(a * 255.0 + 0.5, 0.0, 255.0));\n\n  // Pack RGBA channels into a single u32 (Little Endian)\n  let packed = ir | (ig << 8u) | (ib << 16u) | (ia << 24u);\n\n  let index = id.y * dims.x + id.x;\n  outputBuf[index] = packed;\n}\n`\n\nexport const readbackShader = tgpu.resolve({\n  template: readbackShaderTemplate,\n  externals: {}\n})\n","import * as d from 'typegpu/data'\nimport { StrokePoint } from './gpuSchema'\nimport {\n  brushFragment,\n  brushVertex,\n  blitShader,\n  compositeShader,\n  readbackShader\n} from './brushShaders'\n\n// ... (rest of the file)\n\nconst QUAD_VERTS = new Float32Array([-1, -1, 1, -1, 1, 1, -1, 1])\nconst QUAD_INDICES = new Uint16Array([0, 1, 2, 0, 2, 3])\n\nconst UNIFORM_SIZE = 48 // Uniform buffer size aligned to 16 bytes\nconst STROKE_STRIDE = d.sizeOf(StrokePoint) // 16\nconst MAX_STROKES = 10000\n\nexport class GPUBrushRenderer {\n  private device: GPUDevice\n\n  // Buffers\n  private quadVertexBuffer: GPUBuffer\n  private indexBuffer: GPUBuffer\n  private instanceBuffer: GPUBuffer\n  private uniformBuffer: GPUBuffer\n\n  // Pipelines\n  private renderPipeline: GPURenderPipeline // Standard alpha blending pipeline\n  private accumulatePipeline: GPURenderPipeline // Maximum coverage pipeline for stroke accumulation\n  private blitPipeline: GPURenderPipeline\n  private compositePipeline: GPURenderPipeline // Composite pipeline that applies opacity\n  private compositePipelinePreview: GPURenderPipeline // Pipeline for rendering to the preview canvas\n  private erasePipeline: GPURenderPipeline // Pipeline for erasing (Destination Out)\n  private erasePipelinePreview: GPURenderPipeline // Eraser pipeline for the preview canvas\n  readbackPipeline: GPUComputePipeline // Compute pipeline for texture readback\n\n  // Bind Group Layouts\n  private uniformBindGroupLayout: GPUBindGroupLayout\n  private textureBindGroupLayout: GPUBindGroupLayout\n\n  // Shared Bind Groups\n  private mainUniformBindGroup: GPUBindGroup\n\n  // Textures\n  private currentStrokeTexture: GPUTexture | null = null\n  private currentStrokeView: GPUTextureView | null = null\n\n  // Cached Bind Groups\n  private compositeTextureBindGroup: GPUBindGroup | null = null\n  private previewTextureBindGroup: GPUBindGroup | null = null\n\n  // Removed separate uniform bind groups as we will use mainUniformBindGroup\n\n  private lastReadbackTexture: GPUTexture | null = null\n  private lastReadbackBuffer: GPUBuffer | null = null\n  private readbackBindGroup: GPUBindGroup | null = null\n\n  private lastBackgroundTexture: GPUTexture | null = null\n  private backgroundBindGroup: GPUBindGroup | null = null\n\n  constructor(\n    device: GPUDevice,\n    presentationFormat: GPUTextureFormat = 'rgba8unorm'\n  ) {\n    this.device = device\n\n    // --- 1. Initialize Buffers ---\n    this.quadVertexBuffer = device.createBuffer({\n      size: QUAD_VERTS.byteLength,\n      usage: GPUBufferUsage.VERTEX,\n      mappedAtCreation: true\n    })\n    new Float32Array(this.quadVertexBuffer.getMappedRange()).set(QUAD_VERTS)\n    this.quadVertexBuffer.unmap()\n\n    this.indexBuffer = device.createBuffer({\n      size: QUAD_INDICES.byteLength,\n      usage: GPUBufferUsage.INDEX,\n      mappedAtCreation: true\n    })\n    new Uint16Array(this.indexBuffer.getMappedRange()).set(QUAD_INDICES)\n    this.indexBuffer.unmap()\n\n    this.instanceBuffer = device.createBuffer({\n      size: MAX_STROKES * STROKE_STRIDE,\n      usage: GPUBufferUsage.VERTEX | GPUBufferUsage.COPY_DST\n    })\n\n    this.uniformBuffer = device.createBuffer({\n      size: UNIFORM_SIZE,\n      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST\n    })\n\n    // --- 2. Brush Shader (Drawing) ---\n    const brushModuleV = device.createShaderModule({ code: brushVertex })\n    const brushModuleF = device.createShaderModule({ code: brushFragment })\n\n    // Create explicit bind group layouts\n    this.uniformBindGroupLayout = device.createBindGroupLayout({\n      entries: [\n        {\n          binding: 0,\n          visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT,\n          buffer: { type: 'uniform' }\n        }\n      ]\n    })\n\n    this.textureBindGroupLayout = device.createBindGroupLayout({\n      entries: [\n        {\n          binding: 0,\n          visibility: GPUShaderStage.FRAGMENT,\n          texture: {} // default is float, 2d\n        }\n      ]\n    })\n\n    this.mainUniformBindGroup = device.createBindGroup({\n      layout: this.uniformBindGroupLayout,\n      entries: [{ binding: 0, resource: { buffer: this.uniformBuffer } }]\n    })\n\n    const renderPipelineLayout = device.createPipelineLayout({\n      bindGroupLayouts: [this.uniformBindGroupLayout]\n    })\n\n    // Standard Render Pipeline (Alpha Blend)\n    this.renderPipeline = device.createRenderPipeline({\n      layout: renderPipelineLayout,\n      vertex: {\n        module: brushModuleV,\n        entryPoint: 'vs',\n        buffers: [\n          {\n            arrayStride: 8,\n            stepMode: 'vertex',\n            attributes: [{ shaderLocation: 0, offset: 0, format: 'float32x2' }] // Quad vertex attributes\n          },\n          {\n            arrayStride: 16,\n            stepMode: 'instance',\n            attributes: [\n              { shaderLocation: 1, offset: 0, format: 'float32x2' }, // Instance attributes: position\n              { shaderLocation: 2, offset: 8, format: 'float32' }, // size\n              { shaderLocation: 3, offset: 12, format: 'float32' } // pressure\n            ]\n          }\n        ]\n      },\n      fragment: {\n        module: brushModuleF,\n        entryPoint: 'fs',\n        targets: [\n          {\n            format: 'rgba8unorm',\n            blend: {\n              color: {\n                srcFactor: 'one',\n                dstFactor: 'one-minus-src-alpha',\n                operation: 'add'\n              },\n              alpha: {\n                srcFactor: 'one',\n                dstFactor: 'one-minus-src-alpha',\n                operation: 'add'\n              }\n            }\n          }\n        ]\n      },\n      primitive: { topology: 'triangle-list' }\n    })\n\n    // Keep the highest coverage reached by each stroke sample.\n    this.accumulatePipeline = device.createRenderPipeline({\n      layout: renderPipelineLayout,\n      vertex: {\n        module: brushModuleV,\n        entryPoint: 'vs',\n        buffers: [\n          {\n            arrayStride: 8,\n            stepMode: 'vertex',\n            attributes: [{ shaderLocation: 0, offset: 0, format: 'float32x2' }]\n          },\n          {\n            arrayStride: 16,\n            stepMode: 'instance',\n            attributes: [\n              { shaderLocation: 1, offset: 0, format: 'float32x2' },\n              { shaderLocation: 2, offset: 8, format: 'float32' },\n              { shaderLocation: 3, offset: 12, format: 'float32' }\n            ]\n          }\n        ]\n      },\n      fragment: {\n        module: brushModuleF,\n        entryPoint: 'fs',\n        targets: [\n          {\n            format: 'rgba8unorm',\n            blend: {\n              color: {\n                srcFactor: 'one',\n                dstFactor: 'one',\n                operation: 'max'\n              },\n              alpha: {\n                srcFactor: 'one',\n                dstFactor: 'one',\n                operation: 'max'\n              }\n            }\n          }\n        ]\n      },\n      primitive: { topology: 'triangle-list' }\n    })\n\n    // --- 3. Blit Pipeline (For Preview) ---\n    const blitPipelineLayout = device.createPipelineLayout({\n      bindGroupLayouts: [this.textureBindGroupLayout]\n    })\n\n    this.blitPipeline = device.createRenderPipeline({\n      layout: blitPipelineLayout,\n      vertex: {\n        module: device.createShaderModule({ code: blitShader }),\n        entryPoint: 'vs'\n      },\n      fragment: {\n        module: device.createShaderModule({ code: blitShader }),\n        entryPoint: 'fs',\n        targets: [\n          {\n            format: presentationFormat, // Use the presentation format\n            blend: {\n              color: {\n                srcFactor: 'one',\n                dstFactor: 'one-minus-src-alpha',\n                operation: 'add'\n              },\n              alpha: {\n                srcFactor: 'one',\n                dstFactor: 'one-minus-src-alpha',\n                operation: 'add'\n              }\n            }\n          }\n        ]\n      },\n      primitive: { topology: 'triangle-list' }\n    })\n\n    // --- 4. Composite Pipeline ---\n\n    const compositePipelineLayout = device.createPipelineLayout({\n      bindGroupLayouts: [\n        this.textureBindGroupLayout,\n        this.uniformBindGroupLayout\n      ]\n    })\n\n    // Standard composite pipeline for offscreen textures\n    this.compositePipeline = device.createRenderPipeline({\n      layout: compositePipelineLayout,\n      vertex: {\n        module: device.createShaderModule({ code: compositeShader }),\n        entryPoint: 'vs'\n      },\n      fragment: {\n        module: device.createShaderModule({ code: compositeShader }),\n        entryPoint: 'fs',\n        targets: [\n          {\n            format: 'rgba8unorm',\n            blend: {\n              color: {\n                srcFactor: 'one',\n                dstFactor: 'one-minus-src-alpha',\n                operation: 'add'\n              },\n              alpha: {\n                srcFactor: 'one',\n                dstFactor: 'one-minus-src-alpha',\n                operation: 'add'\n              }\n            }\n          }\n        ]\n      },\n      primitive: { topology: 'triangle-list' }\n    })\n\n    // Composite pipeline for the preview canvas\n    this.compositePipelinePreview = device.createRenderPipeline({\n      layout: compositePipelineLayout,\n      vertex: {\n        module: device.createShaderModule({ code: compositeShader }),\n        entryPoint: 'vs'\n      },\n      fragment: {\n        module: device.createShaderModule({ code: compositeShader }),\n        entryPoint: 'fs',\n        targets: [\n          {\n            format: presentationFormat,\n            blend: {\n              color: {\n                srcFactor: 'one',\n                dstFactor: 'one-minus-src-alpha',\n                operation: 'add'\n              },\n              alpha: {\n                srcFactor: 'one',\n                dstFactor: 'one-minus-src-alpha',\n                operation: 'add'\n              }\n            }\n          }\n        ]\n      },\n      primitive: { topology: 'triangle-list' }\n    })\n\n    // --- 5. Erase Pipeline (Destination Out) ---\n    // Standard erase pipeline for offscreen textures\n    this.erasePipeline = device.createRenderPipeline({\n      layout: compositePipelineLayout,\n      vertex: {\n        module: device.createShaderModule({ code: compositeShader }),\n        entryPoint: 'vs'\n      },\n      fragment: {\n        module: device.createShaderModule({ code: compositeShader }),\n        entryPoint: 'fs',\n        targets: [\n          {\n            format: 'rgba8unorm',\n            blend: {\n              color: {\n                srcFactor: 'zero',\n                dstFactor: 'one-minus-src-alpha', // dst * (1 - src_alpha)\n                operation: 'add'\n              },\n              alpha: {\n                srcFactor: 'zero',\n                dstFactor: 'one-minus-src-alpha', // dst_alpha * (1 - src_alpha)\n                operation: 'add'\n              }\n            }\n          }\n        ]\n      },\n      primitive: { topology: 'triangle-list' }\n    })\n\n    // Erase pipeline for the preview canvas\n    this.erasePipelinePreview = device.createRenderPipeline({\n      layout: compositePipelineLayout,\n      vertex: {\n        module: device.createShaderModule({ code: compositeShader }),\n        entryPoint: 'vs'\n      },\n      fragment: {\n        module: device.createShaderModule({ code: compositeShader }),\n        entryPoint: 'fs',\n        targets: [\n          {\n            format: presentationFormat,\n            blend: {\n              color: {\n                srcFactor: 'zero',\n                dstFactor: 'one-minus-src-alpha',\n                operation: 'add'\n              },\n              alpha: {\n                srcFactor: 'zero',\n                dstFactor: 'one-minus-src-alpha',\n                operation: 'add'\n              }\n            }\n          }\n        ]\n      },\n      primitive: { topology: 'triangle-list' }\n    })\n\n    // --- 6. Readback Pipeline (Compute) ---\n    this.readbackPipeline = device.createComputePipeline({\n      layout: 'auto',\n      compute: {\n        module: device.createShaderModule({ code: readbackShader }),\n        entryPoint: 'main'\n      }\n    })\n  }\n\n  public prepareStroke(width: number, height: number) {\n    // Initialize or resize the accumulation texture\n    if (\n      !this.currentStrokeTexture ||\n      this.currentStrokeTexture.width !== width ||\n      this.currentStrokeTexture.height !== height\n    ) {\n      if (this.currentStrokeTexture) this.currentStrokeTexture.destroy()\n      this.currentStrokeTexture = this.device.createTexture({\n        size: [width, height],\n        format: 'rgba8unorm',\n        usage:\n          GPUTextureUsage.RENDER_ATTACHMENT |\n          GPUTextureUsage.TEXTURE_BINDING |\n          GPUTextureUsage.COPY_SRC\n      })\n      this.currentStrokeView = this.currentStrokeTexture.createView()\n\n      // Invalidate texture-dependent bind groups\n      this.compositeTextureBindGroup = null\n      this.previewTextureBindGroup = null\n      // Readback bind group might also be invalid if it was using the old texture\n      if (this.lastReadbackTexture === this.currentStrokeTexture) {\n        this.readbackBindGroup = null\n        this.lastReadbackTexture = null\n      }\n    }\n\n    // Clear the accumulation texture\n    const encoder = this.device.createCommandEncoder()\n    const pass = encoder.beginRenderPass({\n      colorAttachments: [\n        {\n          view: this.currentStrokeView!,\n          loadOp: 'clear',\n          clearValue: { r: 0, g: 0, b: 0, a: 0 },\n          storeOp: 'store'\n        }\n      ]\n    })\n    pass.end()\n    this.device.queue.submit([encoder.finish()])\n  }\n\n  public renderStrokeToAccumulator(\n    points: { x: number; y: number; pressure: number }[],\n    settings: {\n      size: number\n      coverage: number\n      hardness: number\n      color: [number, number, number]\n      width: number\n      height: number\n      brushShape: number\n    }\n  ) {\n    if (!this.currentStrokeView) return\n    // Render stroke using accumulation pipeline\n    this.renderStrokeInternal(\n      this.currentStrokeView,\n      this.accumulatePipeline,\n      points,\n      { ...settings, opacity: settings.coverage }\n    )\n  }\n\n  public compositeStroke(\n    targetView: GPUTextureView,\n    settings: {\n      opacity: number\n      color: [number, number, number]\n      hardness: number // Required for uniform buffer layout\n      screenSize: [number, number]\n      brushShape: number\n      isErasing?: boolean\n    }\n  ) {\n    if (!this.currentStrokeTexture) return\n\n    // Update uniforms for the composite pass\n    const buffer = new ArrayBuffer(UNIFORM_SIZE)\n    const f32 = new Float32Array(buffer)\n    const u32 = new Uint32Array(buffer)\n\n    f32[0] = settings.color[0]\n    f32[1] = settings.color[1]\n    f32[2] = settings.color[2]\n    f32[3] = settings.opacity\n    f32[4] = settings.hardness\n    f32[5] = 0 // Padding\n    f32[6] = settings.screenSize[0]\n    f32[7] = settings.screenSize[1]\n    u32[8] = settings.brushShape // Brush shape: 0=Circle, 1=Square\n    this.device.queue.writeBuffer(this.uniformBuffer, 0, buffer)\n\n    const encoder = this.device.createCommandEncoder()\n\n    // Choose pipeline based on operation\n    const pipeline = settings.isErasing\n      ? this.erasePipeline\n      : this.compositePipeline\n\n    // 1. Texture Bind Group (Group 0)\n    if (!this.compositeTextureBindGroup) {\n      this.compositeTextureBindGroup = this.device.createBindGroup({\n        layout: this.textureBindGroupLayout,\n        entries: [\n          { binding: 0, resource: this.currentStrokeTexture.createView() }\n        ]\n      })\n    }\n\n    // 2. Uniform Bind Group (Group 1) - Use shared mainUniformBindGroup\n    // It is compatible because we used the same layout\n\n    const pass = encoder.beginRenderPass({\n      colorAttachments: [\n        {\n          view: targetView,\n          loadOp: 'load',\n          storeOp: 'store'\n        }\n      ]\n    })\n\n    pass.setPipeline(pipeline)\n    pass.setBindGroup(0, this.compositeTextureBindGroup)\n    pass.setBindGroup(1, this.mainUniformBindGroup)\n    pass.draw(3)\n    pass.end()\n\n    this.device.queue.submit([encoder.finish()])\n  }\n\n  // Direct rendering method\n  public renderStroke(\n    targetView: GPUTextureView,\n    points: { x: number; y: number; pressure: number }[],\n    settings: {\n      size: number\n      opacity: number\n      hardness: number\n      color: [number, number, number]\n      width: number\n      height: number\n      brushShape: number\n    }\n  ) {\n    this.renderStrokeInternal(targetView, this.renderPipeline, points, settings)\n  }\n\n  private renderStrokeInternal(\n    targetView: GPUTextureView,\n    pipeline: GPURenderPipeline,\n    points: { x: number; y: number; pressure: number }[],\n    settings: {\n      size: number\n      opacity: number\n      hardness: number\n      color: [number, number, number]\n      width: number\n      height: number\n      brushShape: number\n    }\n  ) {\n    if (points.length === 0) return\n\n    // 1. Update Uniforms\n    const buffer = new ArrayBuffer(UNIFORM_SIZE)\n    const f32 = new Float32Array(buffer)\n    const u32 = new Uint32Array(buffer)\n\n    f32[0] = settings.color[0]\n    f32[1] = settings.color[1]\n    f32[2] = settings.color[2]\n    f32[3] = settings.opacity\n    f32[4] = settings.hardness\n    f32[5] = 0 // Padding\n    f32[6] = settings.width\n    f32[7] = settings.height\n    u32[8] = settings.brushShape\n    this.device.queue.writeBuffer(this.uniformBuffer, 0, buffer)\n\n    // 2. Batch Rendering\n    let processedPoints = 0\n    while (processedPoints < points.length) {\n      const batchSize = Math.min(points.length - processedPoints, MAX_STROKES)\n      const iData = new Float32Array(batchSize * 4)\n\n      for (let i = 0; i < batchSize; i++) {\n        const p = points[processedPoints + i]\n        iData[i * 4 + 0] = p.x\n        iData[i * 4 + 1] = p.y\n        iData[i * 4 + 2] = settings.size\n        iData[i * 4 + 3] = p.pressure\n      }\n\n      this.device.queue.writeBuffer(this.instanceBuffer, 0, iData)\n\n      // 3. Render Pass\n      const encoder = this.device.createCommandEncoder()\n      const pass = encoder.beginRenderPass({\n        colorAttachments: [\n          {\n            view: targetView,\n            loadOp: 'load',\n            storeOp: 'store'\n          }\n        ]\n      })\n\n      pass.setPipeline(pipeline)\n      pass.setBindGroup(0, this.mainUniformBindGroup)\n      pass.setVertexBuffer(0, this.quadVertexBuffer)\n      pass.setVertexBuffer(1, this.instanceBuffer)\n      pass.setIndexBuffer(this.indexBuffer, 'uint16')\n      pass.drawIndexed(6, batchSize)\n      pass.end()\n\n      this.device.queue.submit([encoder.finish()])\n\n      processedPoints += batchSize\n    }\n  }\n\n  // Blit the accumulated stroke to the preview canvas\n  public blitToCanvas(\n    destinationCtx: GPUCanvasContext,\n    settings: {\n      opacity: number\n      color: [number, number, number]\n      hardness: number\n      screenSize: [number, number]\n      brushShape: number\n      isErasing?: boolean\n    },\n    backgroundTexture?: GPUTexture\n  ) {\n    const encoder = this.device.createCommandEncoder()\n    const destView = destinationCtx.getCurrentTexture().createView()\n\n    if (backgroundTexture) {\n      // Draw background texture to allow erasing effect on existing content\n      if (\n        this.lastBackgroundTexture !== backgroundTexture ||\n        !this.backgroundBindGroup\n      ) {\n        this.backgroundBindGroup = this.device.createBindGroup({\n          layout: this.textureBindGroupLayout,\n          entries: [{ binding: 0, resource: backgroundTexture.createView() }]\n        })\n        this.lastBackgroundTexture = backgroundTexture\n      }\n\n      const pass = encoder.beginRenderPass({\n        colorAttachments: [\n          {\n            view: destView,\n            loadOp: 'clear', // Clear attachment before drawing\n            clearValue: { r: 0, g: 0, b: 0, a: 0 },\n            storeOp: 'store'\n          }\n        ]\n      })\n      pass.setPipeline(this.blitPipeline)\n      pass.setBindGroup(0, this.backgroundBindGroup)\n      pass.draw(3)\n      pass.end()\n    } else {\n      // Clear the destination texture\n      const clearPass = encoder.beginRenderPass({\n        colorAttachments: [\n          {\n            view: destView,\n            loadOp: 'clear',\n            clearValue: { r: 0, g: 0, b: 0, a: 0 },\n            storeOp: 'store'\n          }\n        ]\n      })\n      clearPass.end()\n    }\n\n    // Draw the accumulated stroke\n    if (this.currentStrokeTexture) {\n      // Update uniforms for the preview pass\n      const buffer = new ArrayBuffer(UNIFORM_SIZE)\n      const f32 = new Float32Array(buffer)\n      const u32 = new Uint32Array(buffer)\n\n      f32[0] = settings.color[0]\n      f32[1] = settings.color[1]\n      f32[2] = settings.color[2]\n      f32[3] = settings.opacity\n      f32[4] = settings.hardness\n      f32[5] = 0 // Padding\n      f32[6] = settings.screenSize[0]\n      f32[7] = settings.screenSize[1]\n      u32[8] = settings.brushShape\n      this.device.queue.writeBuffer(this.uniformBuffer, 0, buffer)\n\n      // Select preview pipeline based on operation\n      const pipeline = settings.isErasing\n        ? this.erasePipelinePreview\n        : this.compositePipelinePreview\n\n      // 1. Texture Bind Group (Group 0)\n      if (!this.previewTextureBindGroup) {\n        this.previewTextureBindGroup = this.device.createBindGroup({\n          layout: this.textureBindGroupLayout,\n          entries: [\n            { binding: 0, resource: this.currentStrokeTexture.createView() }\n          ]\n        })\n      }\n\n      // 2. Uniform Bind Group (Group 1) - Use shared mainUniformBindGroup\n\n      const passStroke = encoder.beginRenderPass({\n        colorAttachments: [\n          {\n            view: destView,\n            loadOp: 'load', // Load the previous pass result\n            storeOp: 'store'\n          }\n        ]\n      })\n      passStroke.setPipeline(pipeline)\n      passStroke.setBindGroup(0, this.previewTextureBindGroup)\n      passStroke.setBindGroup(1, this.mainUniformBindGroup)\n      passStroke.draw(3)\n      passStroke.end()\n    }\n\n    this.device.queue.submit([encoder.finish()])\n  }\n\n  // Clear the preview canvas\n  public clearPreview(destinationCtx: GPUCanvasContext) {\n    const encoder = this.device.createCommandEncoder()\n    const pass = encoder.beginRenderPass({\n      colorAttachments: [\n        {\n          view: destinationCtx.getCurrentTexture().createView(),\n          loadOp: 'clear',\n          clearValue: { r: 0, g: 0, b: 0, a: 0 },\n          storeOp: 'store'\n        }\n      ]\n    })\n    pass.end()\n    this.device.queue.submit([encoder.finish()])\n  }\n\n  public prepareReadback(texture: GPUTexture, outputBuffer: GPUBuffer) {\n    if (\n      this.lastReadbackTexture !== texture ||\n      this.lastReadbackBuffer !== outputBuffer ||\n      !this.readbackBindGroup\n    ) {\n      this.readbackBindGroup = this.device.createBindGroup({\n        layout: this.readbackPipeline.getBindGroupLayout(0),\n        entries: [\n          { binding: 0, resource: texture.createView() },\n          { binding: 1, resource: { buffer: outputBuffer } }\n        ]\n      })\n      this.lastReadbackTexture = texture\n      this.lastReadbackBuffer = outputBuffer\n    }\n\n    const encoder = this.device.createCommandEncoder()\n    const pass = encoder.beginComputePass()\n    pass.setPipeline(this.readbackPipeline)\n    pass.setBindGroup(0, this.readbackBindGroup)\n\n    const width = texture.width\n    const height = texture.height\n    // Dispatch workgroups based on texture dimensions (8x8 block size)\n    pass.dispatchWorkgroups(Math.ceil(width / 8), Math.ceil(height / 8))\n    pass.end()\n\n    this.device.queue.submit([encoder.finish()])\n  }\n\n  public destroy() {\n    this.quadVertexBuffer.destroy()\n    this.indexBuffer.destroy()\n    this.instanceBuffer.destroy()\n    this.uniformBuffer.destroy()\n    if (this.currentStrokeTexture) this.currentStrokeTexture.destroy()\n\n    // Clear cached bind groups\n    this.compositeTextureBindGroup = null\n    this.previewTextureBindGroup = null\n    this.readbackBindGroup = null\n    this.backgroundBindGroup = null\n    this.lastReadbackTexture = null\n    this.lastReadbackBuffer = null\n    this.lastBackgroundTexture = null\n  }\n}\n","import type { Point } from '@/extensions/core/maskeditor/types'\n\nimport type { DirtyRect } from './brushDrawingUtils'\n\n/**\n * Computes the clamped dirty-rect coordinates for a putImageData call.\n *\n * Returns the full canvas dimensions when the dirty rect is uninitialised\n * (Infinity sentinels) or the resulting area has zero/negative size.\n */\nexport function clampDirtyRect(\n  rect: DirtyRect,\n  canvasWidth: number,\n  canvasHeight: number\n): { dx: number; dy: number; dw: number; dh: number } {\n  const full = { dx: 0, dy: 0, dw: canvasWidth, dh: canvasHeight }\n  if (rect.minX === Infinity || rect.maxX === -Infinity) return full\n\n  const dx = Math.floor(Math.max(0, rect.minX))\n  const dy = Math.floor(Math.max(0, rect.minY))\n  const dw = Math.ceil(Math.min(canvasWidth, rect.maxX)) - dx\n  const dh = Math.ceil(Math.min(canvasHeight, rect.maxY)) - dy\n\n  return dw > 0 && dh > 0 ? { dx, dy, dw, dh } : full\n}\n\n/**\n * Linearly interpolates a sequence of points at a fixed step size,\n * returning GPU-ready stroke points with pressure=1.\n *\n * When skipResampling is true the input points are returned as-is (used\n * during live preview where the caller has already handled spacing).\n */\nexport function buildStrokePoints(\n  points: Point[],\n  skipResampling: boolean,\n  stepSize: number\n): { x: number; y: number; pressure: number }[] {\n  if (skipResampling) {\n    return points.map((p) => ({ x: p.x, y: p.y, pressure: 1.0 }))\n  }\n  const result: { x: number; y: number; pressure: number }[] = []\n  for (let i = 0; i < points.length - 1; i++) {\n    const p1 = points[i]\n    const p2 = points[i + 1]\n    const steps = Math.max(\n      1,\n      Math.ceil(Math.hypot(p2.x - p1.x, p2.y - p1.y) / stepSize)\n    )\n    for (let s = 0; s <= steps; s++) {\n      const t = s / steps\n      result.push({\n        x: p1.x + (p2.x - p1.x) * t,\n        y: p1.y + (p2.y - p1.y) * t,\n        pressure: 1.0\n      })\n    }\n  }\n  return result\n}\n","/// <reference types=\"@webgpu/types\" />\nimport { onUnmounted, ref, watch } from 'vue'\nimport { tgpu } from 'typegpu'\n\nimport { BrushShape } from '@/extensions/core/maskeditor/types'\nimport type { Point } from '@/extensions/core/maskeditor/types'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\nimport { parseToRgb } from '@/utils/colorUtil'\n\nimport type { DirtyRect } from './brushDrawingUtils'\nimport {\n  premultiplyData,\n  resetDirtyRect,\n  updateDirtyRect\n} from './brushDrawingUtils'\nimport { getEffectiveBrushSize, getEffectiveHardness } from './brushUtils'\nimport { GPUBrushRenderer } from './gpu/GPUBrushRenderer'\nimport { buildStrokePoints, clampDirtyRect } from './gpuUtils'\n\nexport function useGPUResources() {\n  const store = useMaskEditorStore()\n\n  // GPU state — plain variables, not reactive, as Vue doesn't need to track them\n  let maskTexture: GPUTexture | null = null\n  let rgbTexture: GPUTexture | null = null\n  let device: GPUDevice | null = null\n  let renderer: GPUBrushRenderer | null = null\n  let previewContext: GPUCanvasContext | null = null\n\n  // Readback buffers\n  let readbackStorageMask: GPUBuffer | null = null\n  let readbackStorageRgb: GPUBuffer | null = null\n  let readbackStagingMask: GPUBuffer | null = null\n  let readbackStagingRgb: GPUBuffer | null = null\n  let currentBufferSize = 0\n\n  // Reactive state shared with useBrushDrawing\n  const previewCanvas = ref<HTMLCanvasElement | null>(null)\n  const isSavingHistory = ref(false)\n  const dirtyRect = ref<DirtyRect>(resetDirtyRect())\n\n  const hasRenderer = ref(false)\n\n  const isRecreatingTextures = ref(false)\n\n  // ── Watchers ────────────────────────────────────────────────────────────────\n\n  watch(\n    () => store.clearTrigger,\n    () => clearGPU()\n  )\n\n  watch(\n    () => store.canvasHistory.currentStateIndex,\n    async () => {\n      if (isSavingHistory.value) return\n      await updateGPUFromCanvas()\n      if (renderer && previewContext) renderer.clearPreview(previewContext)\n    }\n  )\n\n  watch(\n    () => store.gpuTexturesNeedRecreation,\n    async (needsRecreation) => {\n      if (\n        !needsRecreation ||\n        !device ||\n        !store.maskCanvas ||\n        isRecreatingTextures.value\n      )\n        return\n\n      /* c8 ignore start */\n      isRecreatingTextures.value = true\n\n      const width = store.gpuTextureWidth\n      const height = store.gpuTextureHeight\n\n      try {\n        maskTexture?.destroy()\n        maskTexture = null\n        rgbTexture?.destroy()\n        rgbTexture = null\n\n        maskTexture = createTexture(device, width, height)\n        rgbTexture = createTexture(device, width, height)\n\n        if (store.pendingGPUMaskData && store.pendingGPURgbData) {\n          device.queue.writeTexture(\n            { texture: maskTexture },\n            store.pendingGPUMaskData,\n            { bytesPerRow: width * 4 },\n            { width, height }\n          )\n          device.queue.writeTexture(\n            { texture: rgbTexture },\n            store.pendingGPURgbData,\n            { bytesPerRow: width * 4 },\n            { width, height }\n          )\n        } else {\n          await updateGPUFromCanvas()\n        }\n\n        if (previewCanvas.value && renderer) {\n          previewCanvas.value.width = width\n          previewCanvas.value.height = height\n        }\n\n        resizeReadbackBuffers(device, width, height)\n      } catch (error) {\n        console.error(\n          '[useGPUResources] Failed to recreate GPU textures:',\n          error\n        )\n      } finally {\n        store.gpuTexturesNeedRecreation = false\n        store.gpuTextureWidth = 0\n        store.gpuTextureHeight = 0\n        store.pendingGPUMaskData = null\n        store.pendingGPURgbData = null\n        isRecreatingTextures.value = false\n      }\n      /* c8 ignore stop */\n    }\n  )\n\n  onUnmounted(() => {\n    // c8 ignore start\n    renderer?.destroy()\n    renderer = null\n    hasRenderer.value = false\n    maskTexture?.destroy()\n    maskTexture = null\n    rgbTexture?.destroy()\n    rgbTexture = null\n    readbackStorageMask?.destroy()\n    readbackStorageMask = null\n    readbackStorageRgb?.destroy()\n    readbackStorageRgb = null\n    readbackStagingMask?.destroy()\n    readbackStagingMask = null\n    readbackStagingRgb?.destroy()\n    readbackStagingRgb = null\n    previewContext = null\n    previewCanvas.value = null\n    dirtyRect.value = resetDirtyRect()\n    // Device is managed by TGPU root; do not destroy it here\n    // c8 ignore stop\n  })\n\n  // ── Helpers ─────────────────────────────────────────────────────────────────\n\n  /* c8 ignore start — requires a live GPUDevice */\n  function createTexture(\n    gpuDevice: GPUDevice,\n    width: number,\n    height: number\n  ): GPUTexture {\n    return gpuDevice.createTexture({\n      size: [width, height],\n      format: 'rgba8unorm',\n      usage:\n        GPUTextureUsage.TEXTURE_BINDING |\n        GPUTextureUsage.STORAGE_BINDING |\n        GPUTextureUsage.RENDER_ATTACHMENT |\n        GPUTextureUsage.COPY_DST |\n        GPUTextureUsage.COPY_SRC\n    })\n  }\n\n  function resizeReadbackBuffers(\n    gpuDevice: GPUDevice,\n    width: number,\n    height: number\n  ): void {\n    const bufferSize = width * height * 4\n    if (currentBufferSize === bufferSize) return\n\n    readbackStorageMask?.destroy()\n    readbackStorageRgb?.destroy()\n    readbackStagingMask?.destroy()\n    readbackStagingRgb?.destroy()\n\n    readbackStorageMask = gpuDevice.createBuffer({\n      size: bufferSize,\n      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC\n    })\n    readbackStorageRgb = gpuDevice.createBuffer({\n      size: bufferSize,\n      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC\n    })\n    readbackStagingMask = gpuDevice.createBuffer({\n      size: bufferSize,\n      usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ\n    })\n    readbackStagingRgb = gpuDevice.createBuffer({\n      size: bufferSize,\n      usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ\n    })\n    currentBufferSize = bufferSize\n  }\n  /* c8 ignore stop */\n\n  // ── Internal functions ───────────────────────────────────────────────────────\n\n  async function initTypeGPU(): Promise<void> {\n    if (store.tgpuRoot) {\n      /* c8 ignore start */\n      // typegpu vendors its own WebGPU types; align with @webgpu/types\n      device = store.tgpuRoot.device as GPUDevice\n      return\n      /* c8 ignore stop */\n    }\n    try {\n      /* c8 ignore start — requires functional WebGPU hardware */\n      const root = await tgpu.init()\n      store.tgpuRoot = root\n      device = root.device\n      console.warn('✅ TypeGPU initialized! Root:', root)\n      console.warn('Device info:', root.device.limits)\n      /* c8 ignore stop */\n    } catch (error) {\n      const message = error instanceof Error ? error.message : String(error)\n      console.warn('Failed to initialize TypeGPU:', message)\n    }\n  }\n\n  async function updateGPUFromCanvas(): Promise<void> {\n    if (\n      !device ||\n      !maskTexture ||\n      !rgbTexture ||\n      !store.maskCanvas ||\n      !store.maskCtx ||\n      !store.rgbCtx\n    )\n      return\n\n    /* c8 ignore start — requires live GPU device and textures */\n    const w = store.maskCanvas.width\n    const h = store.maskCanvas.height\n\n    const maskData = store.maskCtx.getImageData(0, 0, w, h)\n    premultiplyData(maskData.data)\n    device.queue.writeTexture(\n      { texture: maskTexture },\n      maskData.data,\n      { bytesPerRow: w * 4 },\n      { width: w, height: h }\n    )\n\n    const rgbData = store.rgbCtx.getImageData(0, 0, w, h)\n    premultiplyData(rgbData.data)\n    device.queue.writeTexture(\n      { texture: rgbTexture },\n      rgbData.data,\n      { bytesPerRow: w * 4 },\n      { width: w, height: h }\n    )\n    /* c8 ignore stop */\n  }\n\n  // ── Public API ───────────────────────────────────────────────────────────────\n\n  async function initGPUResources(): Promise<void> {\n    await initTypeGPU()\n\n    if (!store.tgpuRoot || !device) {\n      console.warn('TypeGPU not initialized, skipping GPU resource setup')\n      return\n    }\n    if (\n      !store.maskCanvas ||\n      !store.rgbCanvas ||\n      !store.maskCtx ||\n      !store.rgbCtx\n    ) {\n      console.warn('Canvas contexts not ready, skipping GPU resource setup')\n      return\n    }\n\n    const w = store.maskCanvas.width\n    const h = store.maskCanvas.height\n\n    /* c8 ignore start — requires functional WebGPU hardware */\n    try {\n      console.warn(`🎨 Initializing GPU resources for ${w}x${h} canvas`)\n      maskTexture = createTexture(device, w, h)\n      rgbTexture = createTexture(device, w, h)\n      await updateGPUFromCanvas()\n      console.warn('✅ GPU resources initialized successfully')\n      renderer = new GPUBrushRenderer(\n        device,\n        navigator.gpu.getPreferredCanvasFormat()\n      )\n      hasRenderer.value = true\n      console.warn('✅ Brush renderer initialized')\n    } catch (error) {\n      console.error('Failed to initialize GPU resources:', error)\n      maskTexture = null\n      rgbTexture = null\n    }\n    /* c8 ignore stop */\n  }\n\n  function initPreviewCanvas(canvas: HTMLCanvasElement): void {\n    if (!device) return\n    /* c8 ignore start — requires live GPUDevice and WebGPU canvas context */\n    const ctx = canvas.getContext('webgpu')\n    if (!ctx) return\n    ctx.configure({\n      device,\n      format: navigator.gpu.getPreferredCanvasFormat(),\n      alphaMode: 'premultiplied'\n    })\n    previewContext = ctx\n    previewCanvas.value = canvas\n    console.warn('✅ Preview Canvas Initialized')\n    /* c8 ignore stop */\n  }\n\n  function clearGPU(): void {\n    if (!device || !maskTexture || !rgbTexture || !store.maskCanvas) return\n    /* c8 ignore start — requires live GPUDevice and textures */\n    const w = store.maskCanvas.width\n    const h = store.maskCanvas.height\n    const zeros = new Uint8Array(w * h * 4)\n    device.queue.writeTexture(\n      { texture: maskTexture },\n      zeros,\n      { bytesPerRow: w * 4 },\n      { width: w, height: h }\n    )\n    device.queue.writeTexture(\n      { texture: rgbTexture },\n      zeros,\n      { bytesPerRow: w * 4 },\n      { width: w, height: h }\n    )\n    /* c8 ignore stop */\n  }\n\n  function destroy(): void {\n    renderer?.destroy()\n    maskTexture?.destroy()\n    rgbTexture?.destroy()\n    readbackStorageMask?.destroy()\n    readbackStorageRgb?.destroy()\n    readbackStagingMask?.destroy()\n    readbackStagingRgb?.destroy()\n    renderer = null\n    hasRenderer.value = false\n    maskTexture = null\n    rgbTexture = null\n    readbackStorageMask = null\n    readbackStorageRgb = null\n    readbackStagingMask = null\n    readbackStagingRgb = null\n    currentBufferSize = 0\n    previewContext = null\n    previewCanvas.value = null\n    dirtyRect.value = resetDirtyRect()\n    /* c8 ignore next — tgpuRoot only exists after successful GPU init */\n    if (store.tgpuRoot) {\n      store.tgpuRoot.destroy()\n      store.tgpuRoot = null\n    }\n    device = null\n  }\n\n  // ── Wrappers called by useBrushDrawing ──────────────────────────────────────\n\n  function prepareStroke(): void {\n    if (!renderer || !store.maskCanvas) return\n    /* c8 ignore next */\n    renderer.prepareStroke(store.maskCanvas.width, store.maskCanvas.height)\n  }\n\n  function clearPreview(): void {\n    if (!renderer || !previewContext) return\n    /* c8 ignore next */\n    renderer.clearPreview(previewContext)\n  }\n\n  function compositeStroke(isRgb: boolean, isErasing: boolean): void {\n    if (!renderer || !maskTexture || !rgbTexture || !store.maskCanvas) return\n    /* c8 ignore start — requires live renderer */\n    const targetTex = isRgb ? rgbTexture : maskTexture\n    const { size, hardness, opacity, type } = store.brushSettings\n    const effectiveSize = getEffectiveBrushSize(size, hardness)\n    const effectiveHardness = getEffectiveHardness(\n      size,\n      hardness,\n      effectiveSize\n    )\n    const brushShape = type === BrushShape.Rect ? 1 : 0\n    renderer.compositeStroke(targetTex.createView(), {\n      opacity,\n      color: [0, 0, 0],\n      hardness: effectiveHardness,\n      screenSize: [store.maskCanvas.width, store.maskCanvas.height],\n      brushShape,\n      isErasing\n    })\n    /* c8 ignore stop */\n  }\n\n  async function copyGpuToCanvas(): Promise<{\n    maskData: ImageData\n    rgbData: ImageData\n  }> {\n    if (\n      !device ||\n      !maskTexture ||\n      !rgbTexture ||\n      !store.maskCanvas ||\n      !store.rgbCanvas ||\n      !store.maskCtx ||\n      !store.rgbCtx ||\n      !renderer\n    )\n      throw new Error('GPU resources not ready')\n\n    /* c8 ignore start — requires live GPU device, textures and renderer */\n    const width = store.maskCanvas.width\n    const height = store.maskCanvas.height\n\n    resizeReadbackBuffers(device, width, height)\n\n    renderer.prepareReadback(maskTexture, readbackStorageMask!)\n    renderer.prepareReadback(rgbTexture, readbackStorageRgb!)\n\n    const encoder = device.createCommandEncoder()\n    encoder.copyBufferToBuffer(\n      readbackStorageMask!,\n      0,\n      readbackStagingMask!,\n      0,\n      currentBufferSize\n    )\n    encoder.copyBufferToBuffer(\n      readbackStorageRgb!,\n      0,\n      readbackStagingRgb!,\n      0,\n      currentBufferSize\n    )\n    device.queue.submit([encoder.finish()])\n\n    await Promise.all([\n      readbackStagingMask!.mapAsync(GPUMapMode.READ),\n      readbackStagingRgb!.mapAsync(GPUMapMode.READ)\n    ])\n\n    const maskDataArr = new Uint8ClampedArray(\n      readbackStagingMask!.getMappedRange().slice(0)\n    )\n    const rgbDataArr = new Uint8ClampedArray(\n      readbackStagingRgb!.getMappedRange().slice(0)\n    )\n    readbackStagingMask!.unmap()\n    readbackStagingRgb!.unmap()\n\n    const maskImageData = new ImageData(maskDataArr, width, height)\n    const rgbImageData = new ImageData(rgbDataArr, width, height)\n\n    const { dx, dy, dw, dh } = clampDirtyRect(dirtyRect.value, width, height)\n    store.maskCtx.putImageData(maskImageData, 0, 0, dx, dy, dw, dh)\n    store.rgbCtx.putImageData(rgbImageData, 0, 0, dx, dy, dw, dh)\n\n    return { maskData: maskImageData, rgbData: rgbImageData }\n    /* c8 ignore stop */\n  }\n\n  function gpuRender(points: Point[], skipResampling = false): void {\n    if (!renderer || !maskTexture || !rgbTexture) return\n\n    /* c8 ignore start — requires live renderer */\n    const isRgb = store.activeLayer === 'rgb'\n    const color = resolveColor(isRgb)\n    const stepPercentage =\n      Math.pow(100, store.brushSettings.stepSize / 100) / 100\n    const gpuStepSize = Math.max(1.0, store.brushSettings.size * stepPercentage)\n    const strokePoints = buildStrokePoints(points, skipResampling, gpuStepSize)\n\n    const { size, hardness } = store.brushSettings\n    const effectiveSize = getEffectiveBrushSize(size, hardness)\n    const effectiveHardness = getEffectiveHardness(\n      size,\n      hardness,\n      effectiveSize\n    )\n    const brushShape = store.brushSettings.type === BrushShape.Rect ? 1 : 0\n\n    renderer.renderStrokeToAccumulator(strokePoints, {\n      size: effectiveSize,\n      coverage: 1,\n      hardness: effectiveHardness,\n      color,\n      width: store.maskCanvas!.width,\n      height: store.maskCanvas!.height,\n      brushShape\n    })\n\n    for (const p of strokePoints) {\n      dirtyRect.value = updateDirtyRect(\n        dirtyRect.value,\n        p.x,\n        p.y,\n        effectiveSize\n      )\n    }\n\n    if (previewContext) {\n      const isErasing =\n        store.currentTool === 'eraser' ||\n        store.maskCtx?.globalCompositeOperation === 'destination-out'\n      const targetTex = isRgb ? rgbTexture : maskTexture\n      renderer.blitToCanvas(\n        previewContext,\n        {\n          opacity: store.brushSettings.opacity,\n          color,\n          hardness: effectiveHardness,\n          screenSize: [store.maskCanvas!.width, store.maskCanvas!.height],\n          brushShape,\n          isErasing\n        },\n        targetTex\n      )\n    }\n    /* c8 ignore stop */\n  }\n\n  async function gpuDrawPoint(point: Point, opacity = 1): Promise<void> {\n    if (!renderer) return\n\n    /* c8 ignore start — requires live renderer */\n    const width = store.maskCanvas!.width\n    const height = store.maskCanvas!.height\n    const { size, hardness } = store.brushSettings\n    const effectiveSize = getEffectiveBrushSize(size, hardness)\n    const effectiveHardness = getEffectiveHardness(\n      size,\n      hardness,\n      effectiveSize\n    )\n    const brushShape = store.brushSettings.type === BrushShape.Rect ? 1 : 0\n\n    dirtyRect.value = updateDirtyRect(\n      dirtyRect.value,\n      point.x,\n      point.y,\n      effectiveSize\n    )\n\n    renderer.renderStrokeToAccumulator(\n      [{ x: point.x, y: point.y, pressure: opacity }],\n      {\n        size: effectiveSize,\n        coverage: 1,\n        hardness: effectiveHardness,\n        color: [1, 1, 1],\n        width,\n        height,\n        brushShape\n      }\n    )\n\n    if (maskTexture && previewContext) {\n      const isRgb = store.activeLayer === 'rgb'\n      const isErasing =\n        store.currentTool === 'eraser' ||\n        store.maskCtx?.globalCompositeOperation === 'destination-out'\n      renderer.blitToCanvas(\n        previewContext,\n        {\n          opacity: store.brushSettings.opacity,\n          color: resolveColor(isRgb),\n          hardness: effectiveHardness,\n          screenSize: [width, height],\n          brushShape,\n          isErasing\n        },\n        undefined\n      )\n    }\n    /* c8 ignore stop */\n  }\n\n  // ── Private helpers ─────────────────────────────────────────────────────────\n\n  /* c8 ignore start — only reachable after successful GPU init */\n  function resolveColor(isRgb: boolean): [number, number, number] {\n    if (isRgb) {\n      const c = parseToRgb(store.rgbColor)\n      return [c.r / 255, c.g / 255, c.b / 255]\n    }\n    const c = store.maskColor\n    return [c.r / 255, c.g / 255, c.b / 255]\n  }\n  /* c8 ignore stop */\n\n  return {\n    // Lifecycle — spread into useBrushDrawing's public return\n    initGPUResources,\n    initPreviewCanvas,\n    clearGPU,\n    destroy,\n    // Rendering — called internally by useBrushDrawing\n    gpuRender,\n    gpuDrawPoint,\n    copyGpuToCanvas,\n    // Renderer wrappers — called internally by useBrushDrawing\n    prepareStroke,\n    clearPreview,\n    compositeStroke,\n    // Shared reactive state\n    hasRenderer,\n    previewCanvas,\n    isSavingHistory,\n    dirtyRect\n  }\n}\n","import { debounce } from 'es-toolkit/compat'\n\nimport { getStorageValue, setStorageValue } from '@/scripts/utils'\nimport type { Brush } from '@/extensions/core/maskeditor/types'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\n\nconst STORAGE_KEY = 'maskeditor_brush_settings'\n\ntype StoredBrush = Omit<Brush, 'stepSize'> & { stepSize?: number }\n\nfunction loadBrushFromStorage(): StoredBrush | null {\n  try {\n    const brushString = getStorageValue(STORAGE_KEY)\n    if (brushString) {\n      return JSON.parse(brushString) as StoredBrush\n    }\n    return null\n  } catch (error) {\n    console.error('Failed to load brush from cache:', error)\n    return null\n  }\n}\n\nconst debouncedWrite = debounce((serialized: string): void => {\n  try {\n    setStorageValue(STORAGE_KEY, serialized)\n  } catch (error) {\n    console.error('Failed to save brush to cache:', error)\n  }\n}, 300)\n\nexport function useBrushPersistence() {\n  const store = useMaskEditorStore()\n\n  function save(): void {\n    debouncedWrite(JSON.stringify(store.brushSettings))\n  }\n\n  function loadAndApply(): void {\n    const cached = loadBrushFromStorage()\n    if (!cached) return\n    store.setBrushSize(cached.size)\n    store.setBrushOpacity(cached.opacity)\n    store.setBrushHardness(cached.hardness)\n    store.brushSettings.type = cached.type\n    store.setBrushStepSize(cached.stepSize ?? 5)\n  }\n\n  return { loadAndApply, save }\n}\n","import { nextTick, ref } from 'vue'\n\nimport { CompositionOperation, Tools } from '@/extensions/core/maskeditor/types'\nimport type { Point } from '@/extensions/core/maskeditor/types'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\n\nimport {\n  drawMaskShape,\n  drawRgbShape,\n  resetDirtyRect,\n  updateDirtyRect\n} from './brushDrawingUtils'\nimport { getEffectiveBrushSize, getEffectiveHardness } from './brushUtils'\nimport { resampleSegment } from './splineUtils'\nimport { StrokeProcessor } from './StrokeProcessor'\nimport { useBrushAdjustment } from './useBrushAdjustment'\nimport { useGPUResources } from './useGPUResources'\nimport { useBrushPersistence } from './useBrushPersistence'\nimport { useCoordinateTransform } from './useCoordinateTransform'\n\nexport function useBrushDrawing(initialSettings?: {\n  useDominantAxis?: boolean\n  brushAdjustmentSpeed?: number\n}) {\n  const store = useMaskEditorStore()\n  const coordinateTransform = useCoordinateTransform()\n  const persistence = useBrushPersistence()\n  const { startBrushAdjustment, handleBrushAdjustment } =\n    useBrushAdjustment(initialSettings)\n  const gpu = useGPUResources()\n\n  const isDrawing = ref(false)\n  const isDrawingLine = ref(false)\n  const lineStartPoint = ref<Point | null>(null)\n  const lineRemainder = ref(0)\n  const smoothingLastDrawTime = ref(new Date())\n  const initialDraw = ref(true)\n\n  let strokeProcessor: StrokeProcessor | null = null\n\n  persistence.loadAndApply()\n\n  // ── CPU drawing path ─────────────────────────────────────────────────────────\n\n  function drawShape(point: Point, overrideOpacity?: number) {\n    const brush = store.brushSettings\n    const mask_ctx = store.maskCtx\n    const rgb_ctx = store.rgbCtx\n\n    if (!mask_ctx || !rgb_ctx) throw new Error('Canvas contexts are required')\n\n    const brushRadius = brush.size\n    const hardness = brush.hardness\n    const opacity = overrideOpacity ?? brush.opacity\n    const effectiveRadius = getEffectiveBrushSize(brushRadius, hardness)\n    const effectiveHardness = getEffectiveHardness(\n      brushRadius,\n      hardness,\n      effectiveRadius\n    )\n\n    const isErasing = mask_ctx.globalCompositeOperation === 'destination-out'\n    const currentTool = store.currentTool\n    const isRgbLayer = store.activeLayer === 'rgb'\n\n    if (\n      isRgbLayer &&\n      (currentTool === Tools.Eraser || currentTool === Tools.PaintPen)\n    ) {\n      drawRgbShape(\n        rgb_ctx,\n        point,\n        brush.type,\n        effectiveRadius,\n        effectiveHardness,\n        opacity,\n        store.rgbColor\n      )\n    } else {\n      drawMaskShape(\n        mask_ctx,\n        point,\n        brush.type,\n        effectiveRadius,\n        effectiveHardness,\n        opacity,\n        isErasing,\n        store.maskColor\n      )\n    }\n\n    gpu.dirtyRect.value = updateDirtyRect(\n      gpu.dirtyRect.value,\n      point.x,\n      point.y,\n      effectiveRadius\n    )\n  }\n\n  // ── Drawing orchestration ────────────────────────────────────────────────────\n\n  function initShape(compositionOperation: CompositionOperation) {\n    const blendMode = store.maskBlendMode\n    const mask_ctx = store.maskCtx\n    const rgb_ctx = store.rgbCtx\n\n    if (!mask_ctx || !rgb_ctx) throw new Error('Canvas contexts are required')\n\n    mask_ctx.beginPath()\n    rgb_ctx.beginPath()\n\n    if (compositionOperation === CompositionOperation.SourceOver) {\n      mask_ctx.fillStyle = blendMode\n      mask_ctx.globalCompositeOperation = CompositionOperation.SourceOver\n      rgb_ctx.globalCompositeOperation = CompositionOperation.SourceOver\n    } else {\n      mask_ctx.globalCompositeOperation = CompositionOperation.DestinationOut\n      rgb_ctx.globalCompositeOperation = CompositionOperation.DestinationOut\n    }\n  }\n\n  async function drawWithBetterSmoothing(point: Point): Promise<void> {\n    if (!strokeProcessor) return\n\n    const newPoints = strokeProcessor.addPoint(point)\n\n    if (newPoints.length === 0) {\n      if (gpu.hasRenderer.value && initialDraw.value) {\n        /* c8 ignore next */\n        gpu.gpuRender([], true)\n      }\n      return\n    }\n\n    if (gpu.hasRenderer.value) {\n      /* c8 ignore next */\n      gpu.gpuRender(newPoints, true)\n    } else {\n      for (const p of newPoints) drawShape(p)\n    }\n\n    initialDraw.value = false\n  }\n\n  async function drawLine(\n    p1: Point,\n    p2: Point,\n    compositionOp: CompositionOperation,\n    spacing: number\n  ): Promise<void> {\n    const { points, remainder } = resampleSegment(\n      [p1, p2],\n      spacing,\n      lineRemainder.value\n    )\n    lineRemainder.value = remainder\n    initShape(compositionOp)\n\n    if (gpu.hasRenderer.value) {\n      /* c8 ignore next */\n      gpu.gpuRender(points)\n    } else {\n      for (const point of points) drawShape(point, 1)\n    }\n  }\n\n  async function startDrawing(event: PointerEvent): Promise<void> {\n    isDrawing.value = true\n    gpu.dirtyRect.value = resetDirtyRect()\n\n    try {\n      gpu.prepareStroke()\n\n      const currentTool = store.currentTool\n      const coords = { x: event.offsetX, y: event.offsetY }\n      const coords_canvas = coordinateTransform.screenToCanvas(coords)\n\n      const compositionOp =\n        currentTool === 'eraser' || event.buttons === 2\n          ? CompositionOperation.DestinationOut\n          : CompositionOperation.SourceOver\n\n      const stepPercentage =\n        Math.pow(100, store.brushSettings.stepSize / 100) / 100\n      const targetSpacing = Math.max(\n        1.0,\n        store.brushSettings.size * stepPercentage\n      )\n\n      if (event.shiftKey && lineStartPoint.value) {\n        isDrawingLine.value = true\n        await drawLine(\n          lineStartPoint.value,\n          coords_canvas,\n          compositionOp,\n          targetSpacing\n        )\n      } else {\n        isDrawingLine.value = false\n        initShape(compositionOp)\n        lineRemainder.value = targetSpacing\n      }\n\n      lineStartPoint.value = coords_canvas\n\n      if (gpu.hasRenderer.value && gpu.previewCanvas.value) {\n        /* c8 ignore start */\n        const isRgb = store.activeLayer === 'rgb'\n        if (isRgb && store.rgbCanvas) {\n          store.rgbCanvas.style.opacity = '0'\n          gpu.previewCanvas.value.style.opacity = '1'\n        } else if (!isRgb && store.maskCanvas) {\n          store.maskCanvas.style.opacity = '0'\n          gpu.previewCanvas.value.style.opacity = String(store.maskOpacity)\n        }\n        /* c8 ignore stop */\n      }\n\n      strokeProcessor = new StrokeProcessor(targetSpacing)\n      await drawWithBetterSmoothing(coords_canvas)\n      smoothingLastDrawTime.value = new Date()\n    } catch (error) {\n      /* c8 ignore start */\n      const isRgb = store.activeLayer === 'rgb'\n      if (isRgb && store.rgbCanvas) store.rgbCanvas.style.opacity = '1'\n      else if (!isRgb && store.maskCanvas)\n        store.maskCanvas.style.opacity = String(store.maskOpacity)\n      if (gpu.previewCanvas.value) gpu.previewCanvas.value.style.opacity = '1'\n      gpu.clearPreview()\n      /* c8 ignore stop */\n      console.error('[useBrushDrawing] Failed to start drawing:', error)\n      isDrawing.value = false\n      isDrawingLine.value = false\n    }\n  }\n\n  async function handleDrawing(event: PointerEvent): Promise<void> {\n    const diff = performance.now() - smoothingLastDrawTime.value.getTime()\n    const coords = { x: event.offsetX, y: event.offsetY }\n    const coords_canvas = coordinateTransform.screenToCanvas(coords)\n    const currentTool = store.currentTool\n\n    if (diff > 20 && !isDrawing.value) {\n      requestAnimationFrame(async () => {\n        if (!isDrawing.value) return\n        try {\n          initShape(CompositionOperation.SourceOver)\n          if (gpu.hasRenderer.value) {\n            await gpu.gpuDrawPoint(coords_canvas)\n          } else {\n            drawShape(coords_canvas)\n          }\n        } catch (error) {\n          console.error('[useBrushDrawing] Drawing error:', error)\n        }\n      })\n    } else {\n      requestAnimationFrame(async () => {\n        if (!isDrawing.value) return\n        try {\n          if (currentTool === 'eraser' || event.buttons === 2) {\n            initShape(CompositionOperation.DestinationOut)\n          } else {\n            initShape(CompositionOperation.SourceOver)\n          }\n          await drawWithBetterSmoothing(coords_canvas)\n        } catch (error) {\n          console.error('[useBrushDrawing] Drawing error:', error)\n        }\n      })\n    }\n\n    smoothingLastDrawTime.value = new Date()\n  }\n\n  async function drawEnd(event: PointerEvent): Promise<void> {\n    const coords = { x: event.offsetX, y: event.offsetY }\n    const coords_canvas = coordinateTransform.screenToCanvas(coords)\n\n    if (!isDrawing.value) return\n\n    isDrawing.value = false\n    lineStartPoint.value = coords_canvas\n    initialDraw.value = true\n\n    // Flush remaining stroke points\n    if (strokeProcessor) {\n      const finalPoints = strokeProcessor.endStroke()\n      if (finalPoints.length > 0) {\n        if (gpu.hasRenderer.value) {\n          /* c8 ignore next */\n          gpu.gpuRender(finalPoints, true)\n        } else {\n          for (const p of finalPoints) drawShape(p)\n        }\n      }\n      strokeProcessor = null\n    }\n\n    // Composite GPU stroke into the main texture\n    const isRgb = store.activeLayer === 'rgb'\n    const isErasing =\n      store.currentTool === 'eraser' ||\n      store.maskCtx?.globalCompositeOperation === 'destination-out'\n    gpu.compositeStroke(isRgb, isErasing)\n\n    // Read back GPU result\n    let maskData: ImageData | undefined\n    let rgbData: ImageData | undefined\n    if (gpu.hasRenderer.value) {\n      /* c8 ignore start */\n      try {\n        const result = await gpu.copyGpuToCanvas()\n        maskData = result.maskData\n        rgbData = result.rgbData\n      } catch (error) {\n        console.warn('GPU readback failed, falling back to CPU:', error)\n      }\n      /* c8 ignore stop */\n    }\n\n    // Save to history\n    gpu.isSavingHistory.value = true\n    try {\n      store.canvasHistory.saveState(maskData, rgbData)\n      await nextTick()\n    } finally {\n      gpu.isSavingHistory.value = false\n    }\n\n    gpu.clearPreview()\n\n    // Restore canvas visibility\n    if (isRgb && store.rgbCanvas) {\n      store.rgbCanvas.style.opacity = '1'\n    } else if (!isRgb && store.maskCanvas) {\n      store.maskCanvas.style.opacity = String(store.maskOpacity)\n    }\n    if (gpu.previewCanvas.value) {\n      gpu.previewCanvas.value.style.opacity = '1'\n    }\n  }\n\n  return {\n    startDrawing,\n    handleDrawing,\n    drawEnd,\n    startBrushAdjustment,\n    handleBrushAdjustment,\n    saveBrushSettings: persistence.save,\n    destroy: gpu.destroy,\n    initGPUResources: gpu.initGPUResources,\n    initPreviewCanvas: gpu.initPreviewCanvas,\n    clearGPU: gpu.clearGPU\n  }\n}\n","import { ref, watch } from 'vue'\n\nimport { isMiddleButtonHeld, isMiddlePointerInput } from '@/base/pointerUtils'\nimport type {\n  Point,\n  ImageLayer,\n  ToolInternalSettings\n} from '@/extensions/core/maskeditor/types'\nimport { Tools } from '@/extensions/core/maskeditor/types'\nimport { useApp } from '@/scripts/appInstance'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\nimport { useBrushDrawing } from './useBrushDrawing'\nimport { useCanvasTools } from './useCanvasTools'\nimport { useCoordinateTransform } from './useCoordinateTransform'\nimport type { useKeyboard } from './useKeyboard'\nimport type { usePanAndZoom } from './usePanAndZoom'\n\nexport function useToolManager(\n  keyboard: ReturnType<typeof useKeyboard>,\n  panZoom: ReturnType<typeof usePanAndZoom>\n) {\n  const store = useMaskEditorStore()\n\n  const coordinateTransform = useCoordinateTransform()\n\n  const useDominantAxis = useApp().extensionManager.setting.get(\n    'Comfy.MaskEditor.UseDominantAxis'\n  )\n  const brushAdjustmentSpeed = useApp().extensionManager.setting.get(\n    'Comfy.MaskEditor.BrushAdjustmentSpeed'\n  )\n  const brushDrawing = useBrushDrawing({\n    useDominantAxis:\n      typeof useDominantAxis === 'boolean' ? useDominantAxis : undefined,\n    brushAdjustmentSpeed:\n      typeof brushAdjustmentSpeed === 'number'\n        ? brushAdjustmentSpeed\n        : undefined\n  })\n  const canvasTools = useCanvasTools()\n\n  const mouseDownPoint = ref<Point | null>(null)\n\n  const toolSettings: Record<Tools, Partial<ToolInternalSettings>> = {\n    [Tools.MaskPen]: {\n      newActiveLayerOnSet: 'mask'\n    },\n    [Tools.Eraser]: {},\n    [Tools.PaintPen]: {\n      newActiveLayerOnSet: 'rgb'\n    },\n    [Tools.MaskBucket]: {\n      cursor: \"url('/cursor/paintBucket.png') 30 25, auto\",\n      newActiveLayerOnSet: 'mask'\n    },\n    [Tools.MaskColorFill]: {\n      cursor: \"url('/cursor/colorSelect.png') 15 25, auto\",\n      newActiveLayerOnSet: 'mask'\n    }\n  }\n\n  const setActiveLayer = (layer: ImageLayer) => {\n    store.activeLayer = layer\n    const currentTool = store.currentTool\n\n    const maskOnlyTools = [Tools.MaskPen, Tools.MaskBucket, Tools.MaskColorFill]\n    if (maskOnlyTools.includes(currentTool) && layer === 'rgb') {\n      switchTool(Tools.PaintPen)\n    }\n\n    if (currentTool === Tools.PaintPen && layer === 'mask') {\n      switchTool(Tools.MaskPen)\n    }\n  }\n\n  const switchTool = (tool: Tools) => {\n    store.currentTool = tool\n\n    const newActiveLayer = toolSettings[tool].newActiveLayerOnSet\n    if (newActiveLayer) {\n      store.activeLayer = newActiveLayer\n    }\n\n    const cursor = toolSettings[tool].cursor\n    const pointerZone = store.pointerZone\n\n    if (cursor && pointerZone) {\n      store.brushVisible = false\n      pointerZone.style.cursor = cursor\n    } else if (pointerZone) {\n      store.brushVisible = true\n      pointerZone.style.cursor = 'none'\n    }\n  }\n\n  const updateCursor = () => {\n    const currentTool = store.currentTool\n    const cursor = toolSettings[currentTool].cursor\n    const pointerZone = store.pointerZone\n\n    if (cursor && pointerZone) {\n      store.brushVisible = false\n      pointerZone.style.cursor = cursor\n    } else if (pointerZone) {\n      store.brushVisible = true\n      pointerZone.style.cursor = 'none'\n    }\n\n    store.brushPreviewGradientVisible = false\n  }\n\n  watch(\n    () => store.currentTool,\n    (newTool) => {\n      if (newTool !== Tools.MaskColorFill) {\n        canvasTools.clearLastColorSelectPoint()\n      }\n    }\n  )\n\n  const handlePointerDown = async (event: PointerEvent): Promise<void> => {\n    event.preventDefault()\n    if (event.pointerType === 'touch') return\n\n    if (event.pointerType === 'pen') {\n      panZoom.addPenPointerId(event.pointerId)\n    }\n\n    if (shouldStartPan(event)) {\n      panZoom.handlePanStart(event)\n\n      store.brushVisible = false\n      return\n    }\n\n    if (store.currentTool === Tools.PaintPen && event.button === 0) {\n      await brushDrawing.startDrawing(event)\n\n      return\n    }\n\n    if (store.currentTool === Tools.PaintPen && event.buttons === 1) {\n      await brushDrawing.handleDrawing(event)\n      return\n    }\n\n    if (store.currentTool === Tools.MaskBucket && event.button === 0) {\n      const offset = { x: event.offsetX, y: event.offsetY }\n      const coords_canvas = coordinateTransform.screenToCanvas(offset)\n      canvasTools.paintBucketFill(coords_canvas)\n      return\n    }\n\n    if (store.currentTool === Tools.MaskColorFill && event.button === 0) {\n      const offset = { x: event.offsetX, y: event.offsetY }\n      const coords_canvas = coordinateTransform.screenToCanvas(offset)\n      await canvasTools.colorSelectFill(coords_canvas)\n      return\n    }\n\n    if (event.altKey && event.button === 2) {\n      store.isAdjustingBrush = true\n      await brushDrawing.startBrushAdjustment(event)\n      return\n    }\n\n    const isDrawingTool = [\n      Tools.MaskPen,\n      Tools.Eraser,\n      Tools.PaintPen\n    ].includes(store.currentTool)\n\n    if ([0, 2].includes(event.button) && isDrawingTool) {\n      await brushDrawing.startDrawing(event)\n      return\n    }\n  }\n\n  const handlePointerMove = async (event: PointerEv