-comfy-menu-bg px-2 py-1 text-center text-sm text-base-foreground\"\n          :min=\"1\"\n          :max=\"250\"\n          :step=\"1\"\n        />\n      </div>\n      <SliderControl\n        v-model=\"brushSizeSliderValue\"\n        class=\"flex-1\"\n        label=\"\"\n        :min=\"0\"\n        :max=\"1\"\n        :step=\"0.001\"\n      />\n    </div>\n\n    <!-- Opacity -->\n    <div class=\"flex flex-col gap-2\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-left font-sans text-xs text-muted-foreground\">\n          {{ t('maskEditor.opacity') }}\n        </span>\n        <input\n          v-model.number=\"brushOpacity\"\n          type=\"number\"\n          class=\"w-16 rounded-md border border-border-default bg-comfy-menu-bg px-2 py-1 text-center text-sm text-base-foreground\"\n          :min=\"0\"\n          :max=\"1\"\n          :step=\"0.01\"\n        />\n      </div>\n      <SliderControl\n        v-model=\"brushOpacity\"\n        class=\"flex-1\"\n        label=\"\"\n        :min=\"0\"\n        :max=\"1\"\n        :step=\"0.01\"\n      />\n    </div>\n\n    <!-- Hardness -->\n    <div class=\"flex flex-col gap-2\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-left font-sans text-xs text-muted-foreground\">\n          {{ t('maskEditor.hardness') }}\n        </span>\n        <input\n          v-model.number=\"brushHardness\"\n          type=\"number\"\n          class=\"w-16 rounded-md border border-border-default bg-comfy-menu-bg px-2 py-1 text-center text-sm text-base-foreground\"\n          :min=\"0\"\n          :max=\"1\"\n          :step=\"0.01\"\n        />\n      </div>\n      <SliderControl\n        v-model=\"brushHardness\"\n        class=\"flex-1\"\n        label=\"\"\n        :min=\"0\"\n        :max=\"1\"\n        :step=\"0.01\"\n      />\n    </div>\n\n    <!-- Step Size -->\n    <div class=\"flex flex-col gap-2\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-left font-sans text-xs text-muted-foreground\">\n          {{ t('maskEditor.stepSize') }}\n        </span>\n        <input\n          v-model.number=\"brushStepSize\"\n          type=\"number\"\n          class=\"w-16 rounded-md border border-border-default bg-comfy-menu-bg px-2 py-1 text-center text-sm text-base-foreground\"\n          :min=\"1\"\n          :max=\"100\"\n          :step=\"1\"\n        />\n      </div>\n      <SliderControl\n        v-model=\"brushStepSize\"\n        class=\"flex-1\"\n        label=\"\"\n        :min=\"1\"\n        :max=\"100\"\n        :step=\"1\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onBeforeUnmount, onMounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { BrushShape } from '@/extensions/core/maskeditor/types'\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport SliderControl from './controls/SliderControl.vue'\n\nconst { t } = useI18n()\nconst store = useMaskEditorStore()\n\nconst colorInputRef = ref<HTMLInputElement>()\n\nconst textButtonClass =\n  'h-7.5 w-32 rounded-[10px] border border-border-default text-base-foreground font-sans transition-colors duration-100 bg-comfy-menu-bg hover:bg-secondary-background-hover'\n\n/* Computed properties that use store setters for validation */\nconst brushSize = computed({\n  get: () => store.brushSettings.size,\n  set: (value: number) => store.setBrushSize(value)\n})\n\nconst rawSliderValue = ref<number | null>(null)\n\nconst brushSizeSliderValue = computed({\n  get: () => {\n    if (rawSliderValue.value !== null) {\n      const cachedSize = Math.round(Math.pow(250, rawSliderValue.value))\n      if (cachedSize === brushSize.value) {\n        return rawSliderValue.value\n      }\n    }\n\n    return Math.log(brushSize.value) / Math.log(250)\n  },\n  set: (value: number) => {\n    rawSliderValue.value = value\n    